SELECT 'moj-all-verified-judgments-review-002-chunk-154' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"d0a8660b-0a64-5e88-936c-2f34422e614a","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -تخلف املدعى عليه عن احلضور رغم تبلغه -يعد احلكم حضوريا يف مواجهته -اليمن تشرع يف جانب أقوى املتداعين -من أدلة اإلثبات اإلقرار اخلطي و الشيك -إلزام املدعى عليه بسداد املبلغ املدعى به.","document_number":"33347755","case_number":"8020","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة االحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/20","year":"1434","subject":"قرض -تخلف املدعى عليه عن احلضور رغم تبلغه -يعد احلكم حضوريا يف مواجهته -اليمن تشرع يف جانب أقوى املتداعين -من أدلة اإلثبات اإلقرار اخلطي و الشيك -إلزام املدعى عليه بسداد املبلغ املدعى به.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/7/20 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33347755 :‬‬\n                            ‫َر ْق ُم الدعوى‪8020 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪/3416304‬ش‪ 2/‬تاريخه‪1434/1/19 :‬هـ‬\n\n\n\n     ‫قــرض ‪ -‬تخلــف املدعــى عليــه عــن احلضــور رغــم تبلغــه ‪ -‬يعــد احلكــم‬\n     ‫حضوريــا يف مواجهتــه‪ -‬اليمــن تشــرع يف جانــب أقــوى املتداعيــن ‪-‬مــن‬\n     ‫أدلــة اإلثبــات اإلقــرار اخلطــي و الشــيك ‪ -‬إلــزام املدعــى عليــه بســداد‬\n                                                              ‫املبلــغ املدعــى بــه‪.‬‬\n\n\n\n\n     ‫مــا قــرره الفقهــاء كشــيخ اإلســام ابــن تيميــة مــن أن اليمــن تشــرع يف‬\n                                                       ‫جانــب أقــوى املتداعيــن‪.‬‬\n\n\n\n\n     ‫حضــر املدعــي ولــم يحضــر املدعــى عليــه مــع تبلغــه ‪ ،‬قــرر القاضــي‬\n     ‫الســير يف نظــر الدعــوى وطلــب مــن املدعــي حتريــر دعــواه ‪ ،‬ادعــى‬\n     ‫املدعــي علــى املدعــى عليــه بأنــه أقرضــه مبلغـ ًا مــن املــال مبوجــب شــيك‬\n     ‫علــى أن يســدد القــرض خــال عــام وانتهــى األجــل ولــم يســدد القــرض‪،‬‬\n     ‫طلــب القاضــي مــن املدعــي البينــة علــى دعــواه ‪ ،‬أبــرز املدعــي صــورة‬\n     ‫الشــيك وإقــرار ًا خطيـ ًا منســوب ًا للمدعــى عليــه ‪ ،‬جــرى االطــاع عليهمــا‬\n     ‫ورصــد مضمونهمــا‪ ،‬جــرى مخاطبــه مؤسســه النقــد لإلفــادة عــن صرف‬\n     ‫املدعــى عليــه للشــيك‪ ،‬وردت اإلجابــة بصــرف املدعــى عليــه لشــيك آخــر‬\n\n\n‫‪63‬‬\n\f‫بنفــس التاريــخ واملبلــغ ‪ ،‬لتقــوي جانــب املدعــى بجــواب مؤسســه النقــد‬\n‫واإلقــرار اخلطــي املنســوب للمدعــى عليــه لــذا طلــب القاضــي مــن املدعــى‬\n‫اليمــن ‪ ،‬حلــف املدعــى اليمــن علــى صحــه دعــواه و أنــه لــم يتســلم مــن‬\n‫املدعــى عليــه شــيئ ًا ‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع املبلــغ‬\n‫املدعــى بــه للمدعــى وعــد احلكــم حضوري ـ ًا ‪ ،‬صــدق احلكــم مــن‬\n                                                      ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫العامــة‬\n    ‫ّ‬     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة‬\n‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة االحســاء برقــم ‪ 8020‬وتاريــخ ‪1431/11/29‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 3140479‬وتاريــخ ‪1431/11/29‬ه ـ حضــر‬\n‫‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬ولــم حتضــر املدعــى‬\n‫عليهــا وبتصفــح املعاملــة وجدنــا أن املدعــى عليــه ‪ ...‬قــد وقــع علــى ورقــة‬\n‫التبليــغ للجلســة املؤرخــة يف ‪1432/5/2‬ه ـ واملوقعــة مــن قبلــه وبســؤال‬\n‫املدعــي عــن دعــواه قــال إننــي أقرضــت املدعــى عليــه مبلغ ـ ًا وقــدره‬\n‫خمســون ألــف ريـ‪ 50000‬ــال يف ‪1430/10/20‬ه ـ مبوجــب الشــيك‬\n‫رقــم ‪ 000111‬يف ‪1430/10/20‬ه ـ علــى البنــك الســعودي األمريكــي‬\n‫علــى أن يســدد القــرض خــال عــام وحتــى تاريخــه لــم يســلمني مبلــغ‬\n‫القــرض وال جــزء منــه أطلــب إلزامــه بتســليمي مبلغ ـ ًا وقــدره خمســون‬\n‫ألــف ريـ‪ 50000‬ــال هــذه دعــواي فطلبــت مــن املدعــي البينــة فقــال البينــة‬\n‫هــي ورقــة إقــرار مكتوبــة بخــط يــده وأبــرز أصــل الورقــة فوجدتهــا‬\n‫طبــق مــا جــاء يف الدعــوى وعليــه فقــد قــررت الكتابــة ملؤسســة النقــد‬\n\n                                                                                     ‫‪64‬‬\n\f     ‫العربــي الســعودي لإلفــادة عــن رقــم الشــيك املذكــور وبيــان مصــدر‬\n     ‫الشــيك واملســتفيد منــه ويف جلســة أخــرى حضــر املدعــي ولــم يحضــر‬\n     ‫املدعــى عليــه وقــد وردنــا جــواب شــرطة ‪ ....‬برقــم ‪ 9/21‬ق ‪ 3103/‬يف‬\n     ‫‪1433/04/06‬ه ـ املتضمــن تعــذر تســليم املدعــى عليــه ‪ ...‬صــورة التبليــغ‬\n     ‫وباإلطــاع علــى البينــة التــي أبرزهــا املدعــي يف اجللســة املاضيــة لــم جنــد‬\n     ‫أنــه مت رصدهــا ونصهــا نعــم أنــا املدعــو ‪ ...‬ســعودي اجلنســية مبوجــب‬\n     ‫رقــم البطاقــة رقــم ‪ ...‬وتاريــخ ‪1404/07/08‬ه ـ الصــادرة مــن ‪ ....‬قــد‬\n     ‫اقترضــت مبلغ ـ ًا وقــدره خمســون ألــف ريــال ‪ 50000‬وذلــك عبــارة عــن‬\n     ‫قرضــة حســنة ويف ذمتــي للمدعــو ‪...‬الــذي اســتلمت منــه املبلــغ بشــيك‬\n     ‫رقــم ‪ 000111‬يف ‪1430/10/20‬ه ـ مــن البنــك األمريكــي وأن أســددها‬\n     ‫خــال عــام مــن تاريخــه واهلل علــى مــا أقــول شــهيد املقــر مبــا فيــه‬\n     ‫‪...‬توقيعــه انتهــى نصــه كمــا جــرى مخاطبــة مؤسســة النقــد العربــي‬\n     ‫الســعودي بخطابنــا رقــم ‪ 33561077‬يف ‪1433/03/23‬ه ـ لإلفــادة عــن‬\n     ‫الشــيك املذكــور يف ورقــة اإلقــرار املرصــودة بعاليــه فــورد اجلــواب برقــم‬\n     ‫‪22/3355‬س‪1779/‬يف ‪1433/05/18‬ه ـ ونصــه إشــارة خلطابكــم‬\n     ‫رقــم ‪ 33561077‬بتاريــخ ‪1433/03/27‬ه ـ بخصــوص اإلفــادة عــن‬\n     ‫الشــيك رقــم ‪ 000111‬بتاريــخ ‪1430/10/20‬ه ـ مببلــغ خمســن ألــف‬\n     ‫ريــال ‪ 50000‬الصــادر مــن حســاب املدعــي ‪ ...‬ســجل مدنــي رقــم ‪...‬لــدى‬\n     ‫مجموعــة ســامبا املاليــة ألمــر املدعــى عليــه ‪ ...‬ســجل مدنــي رقــم ‪...‬وهــل‬\n     ‫صــرف الشــيك أم ال وكيــف مت صرفــه ومــن املســتفيد مــن مبلغــه نــود‬\n     ‫اإلفــادة بأنــه ال يوجــد ســوى حســاب واحــد جــاري لــدى مجموعــة ســامبا‬\n     ‫املاليــة باســم املدعــي وقــد جــرى البحــث يف جميــع العمليــات املنفــذة‬\n     ‫علــى احلســاب منــذ تاريــخ فتحــه يف ‪2005/05/14‬م حتــى تاريخــه‬\n\n\n‫‪65‬‬\n\f‫ولــم تتوصــل املجموعــة للشــيك املشــار لــه علم ـ ًا بــأن مت التوصــل إلــى‬\n‫الشــيك رقــم ‪ 000112‬بــذات التاريــخ واملبلــغ واملســتفيد املدعــى عليــه‬\n‫حيــث مت صرفــه نقــد ًا للمدعــى عليــه بتاريــخ ‪2009/10/10‬م مرفــق‬\n‫نســخة الشــيك بعــد صرفــه ونعيــد لكــم خطابكــم ومرفقاتــه انتهــى‬\n‫نصــه وعليــه فقــد أفهمــت املدعــي بــأن مــا أبــرزه مــن إثبــات يعتبــر قرينــة‬\n‫يتقــوى بــه جانبــه وال بــد مــن ميينــه علــى أنــه أقــرض املدعــى عليــه املبلــغ‬\n‫املدعــى بــه وأنــه لــم يســتلم منــه شــيئ ًا وال يــزال يف ذمــة املدعــى عليــه حتــى‬\n‫اليــوم بعــد تذكيــره بخطــر اليمــن الكاذبــة فاســتعد بــأداء اليمــن‬\n‫ا واهلل العظيــم إننــي أقرضــت املدعــى عليــه ‪ ...‬مبلغـ ًا وقــدره‬      ‫فتلفــظ قائـ ً‬\n‫خمســون ألــف ريــال مبوجــب شــيك ولــم يقــم بتســليمي هــذا القــرض‬\n‫حتــى هــذا اليــوم وال يــزال يف ذمتــه واهلل علــى مــا أقــول شــهيد هكــذا‬\n‫حلــف فبنــاء علــى مــا تقــدم مــن الدعــوى وحيــث طالــب املدعــي املدعــى‬\n‫عليــه باملبلــغ املدعــى بــه وقــدره خمســون ألــف ريــال ولــم يحضــر املدعــي‬\n‫عليــه جلســات الدعــوى وأبــرز املدعــي بينتــه وهــي الورقــة التــي مت رصــد‬\n‫مضمونهــا وكذلــك إفــادة مؤسســة النقــد بــأن املدعــى عليــه املذكــور‬\n‫اســتلم الشــيك املرفــق صورتــه وصرفــه نقــدا وأن مصــدر الشــيك هــو‬\n‫املدعــي وحيــث تقــوي جانــب املدعــي وقــد قــرر بعــض الفقهــاء كشــيخ‬\n‫اإلســام ابــن تيميــة أن اليمــن تشــرع يف جانــب أقــوى املتداعيــن وحلــف‬\n‫املدعــي اليمــن املطلوبــة منــه لــذا فقــد حكمــت بإلــزام املدعــى عليــه ‪...‬‬\n‫بتســليم املدعــي مبلــغ وقــدره خمســون ألــف ريــال وأن احلكــم يف حــق‬\n‫املدعــى عليــه يعتبــر حكم ـ ًا حضوري ـ ًا لتبلغــه مبوعــد إحــدى اجللســات‬\n‫وســيتم تزويــده بنســخة مــن احلكــم لتقــدمي اعتراضــه عليــه خــال املــدة‬\n‫النظاميــة وهــي ثالثــون يومـ ًا مــن تاريــخ تســلمه وأنها إذا مضــت املدة دون‬\n\n\n                                                                                             ‫‪66‬‬\n\f     ‫تقــدمي اإلعتــراض فســوف يســقط حقــه يف طلــب اإلســتئناف ويكتســب‬\n     ‫احلكــم الصفــة القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/06/17‬ه ـ يف متــام الســاعة‬\n                                                          ‫الواحــدة وعشــر دقائــق ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد يف يــوم الســبت تاريــخ ‪1434/2/9‬ه ـ فقــد‬\n     ‫وردت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية برقــم‬\n     ‫‪332007805‬يف ‪1434/2/3‬ه ـ املقيــدة يف هــذه احملكمــة برقــم‬\n     ‫‪34/31669‬يف ‪1434/2/6‬ه ـ وبرفقهــا القــرار الصــادر مــن أصحــاب‬\n     ‫الفضيلــة قضــاة دائــرة األحــوال الشــخصية الثانيــة يف محكمــة‬\n     ‫االســتئناف باملنطقة الشــرقية رقم ‪/3416304‬ش‪2/‬يف ‪1434/1/19‬هـ‬\n     ‫نــص املقصــود منــه بدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n     ‫قررنــا املصادقــة علــى حكــم فضيلتــه واهلل املوفــق قضــاة محكمــة‬\n     ‫االســتئناف وهــم ‪ ...‬و‪...‬ورئيــس الدائــرة د‪...‬وعليــه توقيــع وختــم لــكل‬\n     ‫واحــد منهــم وللبيــان حــرر يف ‪1434/2/9‬ه ـ وصلــى اهلل علــى نبينــا‬\n                                            ‫محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪67‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":63,"source_page_end":67,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5ca676d939ef2e218962078946e8282841ad9361db08795b89d48ee700fa4980","normalized_text_hash":"037880a84ddf361f6267bb373df16ba33f2f9011171ad446eca306b785adcf76","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p63-33347755"},{"id":"6bb9986b-923d-5155-b096-1bfb4dcd828a","document_type":"judgment","category":"judicial","subcategory":"general","title":"إقراض -ادعاء مضاربة -بينة املدعي غير موصلة -شهود املدعى عليه بنفي ادعاء املدعي -تعديل الشهود -رد دعوى -إخاء سبيل.","document_number":"3418117","case_number":"33367047","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة االحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"إقراض -ادعاء مضاربة -بينة املدعي غير موصلة -شهود املدعى عليه بنفي ادعاء املدعي -تعديل الشهود -رد دعوى -إخاء سبيل.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/20 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3418117 :‬‬\n                   ‫َر ْق ُم الدعوى‪33367047 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34178176‬تاريخه‪1434/4/3 :‬هـ‬\n\n\n\n‫إقــراض ‪ -‬ادعــاء مضاربــة ‪ -‬بينــة املدعــي غيــر موصلــة ‪ -‬شــهود املدعــى‬\n‫عليــه بنفــي ادعــاء املدعــي ‪ -‬تعديــل الشــهود ‪ -‬رد دعــوى ‪ -‬إخــاء ســبيل‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                    ‫حكمه ‪.‬‬\n\n\n\n\n‫ادعــى املدعــى علــى املدعــى عليــه أنــه أعطــاه مائــة وخمســة وخمســن‬\n‫ألــف ريــال ليضــارب بهــا ولــم يرجــع إليــه شــيء منهــا وقــد رد املدعــى‬\n‫عليــه هــذه الدعــوى وقــال أن هــذه األمــوال كانــت قرض ـ ًا حســن ًا منــي‬\n‫إليــه وهــو ردهــا إلــي وأحضــر الشــهود علــى ذلــك وعليــه قــرر القاضــي‬\n‫عــدم ثبــوت الدعــوى وإخــاء ســبيل املدعــى عليــه وقــد اعتــرض املدعــي‬\n              ‫علــى احلكــم وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                 ‫‪68‬‬\n\f     ‫العامــة‬\n        ‫ّ‬     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة‬\n     ‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة مبحافظــة االحســاء برقــم ‪ 33367047‬وتاريــخ ‪1433/05/29‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 331008742‬وتاريــخ ‪ 1433/05/29‬ه ـ ففــي‬\n     ‫يــوم الســبت املوافــق‪ 1433/07/19‬ه ـ وفيهــا حضــر املدعــي أصالــة‬\n     ‫‪...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪ ...‬وادعــى علــى احلاضــر معــه‬\n     ‫‪...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪...‬قائــا املدعــي يف حتريــر‬\n     ‫دعــواه إن هــذا احلاضــر معــي قــد اســتلم منــي مبلــغ خمســة وخمســن‬\n     ‫ألــف ريـ‪ 55000‬ــال مبوجــب الشــيك الصــادر مــن البنــك ‪...‬برقــم ‪...‬يف‬\n     ‫‪2001/3/3‬م واســتلم أيضــا مبلــغ مائــة ألــف ريـ‪ 100000‬ــال مبوجــب‬\n     ‫الشــيك الصــادر مــن البنــك ‪...‬برقــم ‪...‬يف ‪1421/11/15‬ه ـ فــكان‬\n     ‫املجمــوع مائــة وخمســة وخمســن ألــف ريـ‪ 155000‬ــال علــى أن أضــارب‬\n     ‫لــه يف األســهم بنســبة ‪ %25‬و‪ %75‬للمدعــى عليــه ولــم يــرد املدعــى عليــه‬\n     ‫املبلــغ وال األربــاح أطلــب إلــزام املدعــى عليــه بإرجــاع املبلــغ املذكــور هذه‬\n     ‫دعواي وبعرض ذلك على املدعى عليه أجاب بقوله إن ماذكره املدعي‬\n     ‫غيــر صحيــح جملــة وتفصيــا والصحيــح أنــي اســتلمت هــذا املبلغ ســدادا‬\n     ‫للمبلــغ الــذي كان يف ذمتــه لــي حيــث أنــه اقتــرض منــي هــذا املبلــغ ومت‬\n     ‫ســداده مبوجــب هــذه الشــيكات هكــذا أجــاب وبســؤالهما عــن بينتهما‬\n     ‫أحضــر املدعــى عليــه شــاهدا يدعــى ‪...‬ســعودي مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪...‬مــن مواليــد ‪1395/5/27‬ه ـ وبســؤال الشــاهد عــن وجــود صلــة‬\n     ‫قرابــه بينــه وبــن املدعــن فأجــاب بقولــه ليــس بينــي وبينهمــا صلــة قرابــه‬\n\n‫‪69‬‬\n\f‫ســوى الصداقــة وبســؤاله عمــا لديــه مــن شــهادة أجــاب بقولــه أشــهد هلل‬\n‫تعالــى بأنــه منــذ أكثــر مــن عشــر ســنوات تقريبــا طلــب منــي ‪...‬مبلغــا مــن‬\n‫املــال فأحضــرت لــه املدعــى عليــه وقــام املدعــى عليــه بإقــراض املدعــي‬\n‫مبلغــا مقــداره مائــه وخمســه وخمســون ألــف ريــال وقــد أخبرنــي املدعــى‬\n‫عليــه بأنــه اســتلم املبلــغ مــن املدعــي مبوجــب شــيكات هــذا مــا لــدي وبــه‬\n‫أشــهد هلل تعالــى وبعــرض الشــاهد وشــهادته علــى املدعــي أجــاب بقولــه‬\n‫إن شــهادة الشــاهد غيــر صحيحــه وأنــا ال أطعــن يف دينــه وأمانتــه هكــذا‬\n‫أجــاب ثــم أحضــر املدعــى عليــه شــاهدا آخــر يدعــى ‪ ...‬ســعودي مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬وهــو مــن مواليــد ‪1390/2/4‬ه ـ وبســؤال الشــاهد‬\n‫عــن وجــود صلــة قرابــه بينــه وبــن املدعــن فأجــاب بقولــه ليــس بينــي‬\n‫وبينهمــا صلــة قرابــه ســوى الصداقــة بينــي وبــن املدعــى عليــه وبســؤاله‬\n‫عمــا لديــه مــن شــهادة أجــاب بقولــه أشــهد هلل تعالــى أنــه منــذ أكثــر‬\n‫مــن عشــر ســنوات أقــرض املدعــى عليــه ‪ ...‬مبلغــا مقــداره مائــه وخمســه‬\n‫وخمســون ألــف ريــال قــرض حســن وقــد كنــت حاضــرا معهمــا وقــد‬\n‫كتــب بهــا ورقــة ثــم أبلغنــا بعــد فتــرة عــواد أنــه اســتلم املبلــغ مــن املدعــي‬\n‫هــذا مــا حصــل وبــه أشــهد هلل تعالــى وبعــرض الشــاهد وشــهادته علــى‬\n‫املدعــي أجــاب بقولــه بــأن شــهادته غيــر صحيحــه وأنــا ال أطعــن يف دينــه‬\n‫وأمانتــه هــذا وقــد جــرى تعديــل الشــاهدين مــن قبــل ‪...‬ســعودي مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬و‪...‬ســعودي مبوجــب الســجل املدنــي رقم ‪...‬وشــهدا‬\n‫بقولهمــا نشــهد هلل تعالــى بعدالــة الشــاهدين املذكوريــن وأنهــا عــدالن‬\n‫وثقــة وإن شــهدا علينــا هكــذا أجابــا فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وحيــث أنكــر املدعــى عليــه دعــوى املدعي وادعى أن اســتالمه‬\n‫هــذا املبلــغ لكونــه قــرض أقرضــه املدعــي وأحضــر البينــة علــى صحــة‬\n\n\n                                                                                            ‫‪70‬‬\n\f     ‫مــا ذكــر املدعــى عليــه وحيــث أنــه ال يحــل مــال امــرىء مســلم إال بطيــب‬\n     ‫نفــس منــه لــذا وجلميــع مــا تقــدم لــم تثبــت لــدي دعــوى املدعــي قبــل‬\n     ‫املدعــى عليــه وثبــت لــدي أن اســتالمه لهــذا املبلــغ كان مقابــل قــرض‬\n     ‫اســتلمه املدعــى عليــه مــن املدعــي وأخليــت ســبيل املدعــى عليــه وبذلــك‬\n     ‫حكمــت وبعرضــه عليهمــا قــرر املدعــي عــدم قناعتــه وطلــب االســتئناف‬\n     ‫فأفهــم باملراجعــة يــوم الســبت ‪1434/1/24‬ه ـ الســتالم صــورة مــن صــك‬\n     ‫احلكــم ليتمكــن مــن تقــدمي الئحــة اعتــراض عليــه ففهــم ذلــك وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n     ‫حــرر يف ‪1434/01/20‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى‬\n     ‫رســولنا محمــد و آلــه وصحبــه أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة‬\n     ‫الدائ ــرة احلقوقيــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية‬\n     ‫علــى املعاملــة الــواردة مــن فضيلــة القائــم بعمــل رئيــس احملكمــة العامــة‬\n     ‫مبحافظة األحســاء برقم ‪ 331008742‬وتاريخ ‪1434/2/19‬هـ واملقيدة‬\n     ‫لــدى احملكمــة برقــم ‪ 34455056‬وتاريــخ ‪1434/2/24‬ه ـ املرفــق بهــا‬\n     ‫الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ... /‬املسـ ّـجل‬\n     ‫برقــم ‪...‬وتاريــخ ‪1434/1/20‬ه ـ اخلــاص بدعــوى‪... /‬ضــد‪... /‬يف قضيــة‬\n     ‫حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n     ‫فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n     ‫املعاملــة قررنــا املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى ضــرورة‬\n     ‫تعديــل لفــظ املدعــي يف الضبــط إلــى لفــظ املدعــى عليــه يف املوضعــن‬\n     ‫املشــار إليهمــا بقلــم الرصــاص يف الصــك عنــد إحضــار الشــاهدين‬\n     ‫وذلــك قبــل بعــث املعاملــة إلــى اجلهــة اإلداريــة املختصــة‪ ،‬ولبيانــه حــرر يف‬\n                                             ‫‪1434/4/2‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n‫‪71‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":68,"source_page_end":71,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"50d61d7f111b1563618e2fcde44553b32a169aea3ef7e03a282006f280dae7bf","normalized_text_hash":"f6a897b0a1008532100e6c57e6fa1d7d528d1ee3a5ca3f18aa129acff2c8c3fd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p68-3418117"},{"id":"e19044ad-5ab8-596d-b3f0-e7225c0409dd","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -ضمان -مطالبة الضامن للمضمون بسداد ما سلمه عنه للمضمون له -محرر عريف وشهادة شهود سند ا للدعوى -طلب اليمن من جانب أقوى املتداعين -اعتبار عدم حضور املدعى عليه املتبلغ باجللسة نكو ال عن اجلواب وقرينه تضعف جانبه وتقوى جانب املدعي -احلكم حضوري يف حالة النكول -رفع احلكم احلضوري إلى محكمة اإلستئناف دون الئحة .","document_number":"34293933","case_number":"33581048","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/10","year":"1434","subject":"قرض -ضمان -مطالبة الضامن للمضمون بسداد ما سلمه عنه للمضمون له -محرر عريف وشهادة شهود سند ا للدعوى -طلب اليمن من جانب أقوى املتداعين -اعتبار عدم حضور املدعى عليه املتبلغ باجللسة نكو ال عن اجلواب وقرينه تضعف جانبه وتقوى جانب املدعي -احلكم حضوري يف حالة النكول -رفع احلكم احلضوري إلى محكمة اإلستئناف دون الئحة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/10 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34293933 :‬‬\n                   ‫َر ْق ُم الدعوى‪33581048 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34356175‬تاريخه‪1434/11/10 :‬هـ‬\n\n\n\n‫قــرض ‪ -‬ضمــان ‪ -‬مطالبــة الضامــن للمضمــون بســداد مــا ســلمه عنــه‬\n‫للمضمــون لــه ‪ -‬محــرر عــريف وشــهادة شــهود ســند ًا للدعــوى ‪ -‬طلــب‬\n‫اليمــن مــن جانــب أقــوى املتداعيــن ‪ -‬اعتبــار عــدم حضــور املدعــى عليه‬\n‫املتبلــغ باجللســة نكــو ًال عــن اجلــواب وقرينــه تضعــف جانبــه وتقــوى‬\n‫جانــب املدعــي ‪ -‬احلكــم حضــوري يف حالــة النكــول ‪ -‬رفــع احلكــم‬\n                       ‫احلضــوري إلــى محكمــة اإلســتئناف دون الئحــة ‪.‬‬\n\n\n\n\n‫املــادة اخلامســة واخلمســون مــن نظــام املرافعــات الشــرعية ولوائحهــا‬\n                                                            ‫التنفيذية ‪.‬‬\n\n\n\n\n‫دعــوى املدعــى ضــد املدعــى عليهــا الغائبــة عــن مجلــس احلكــم التــي‬\n‫تبلغــت مبوعــد اجللســة وحــرر املدعــى دعــواه مضمونهــا أن املدعــى عليهــا‬\n‫اقترضــت مــن شــخص مبلغــا قــدره مئتــا ألــف ريــال وان املدعــى ضمنهــا‬\n‫يف املبلــغ لــدى املقتــرض وأن املدعــى عليهــا لــم تســدد املبلــغ وان املقــرض‬\n‫طالــب املدعــى بالســداد وســلم املدعــى املقــرض كامــل مبلــغ القــرض‬\n‫الــذي يف ذمــة املدعــى عليهــا ‪ ،‬أحضــر املدعــى بينــة موصلــه علــى صحــة‬\n\n                                                                                     ‫‪72‬‬\n\f     ‫الدعــوى عبــارة ســندين وشــاهدين مت تعديلهمــا التعديــل الشــرعي ‪ ،‬قــرر‬\n     ‫ناظــر القضيــة طلــب اليمــن مــن املدعى على صحة دعــواه وحلف املدعى‬\n     ‫علــى صحــة الدعــوى ‪ ،‬قــرر ناظــر القضيــة انــه بنــاء علــى الدعــوى والبينة‬\n     ‫املوصلــة واليمــن مــن املدعــى وألن امتنــاع املدعــى عليهــا مــن حضــور‬\n     ‫جلســات القضيــة يضعــف جانبهــا ويقــوى جانــب املدعــي وملشــروعية‬\n     ‫اليمــن يف جانــب أقــوى املتداعــن وملــا جــاء يف أســباب احلكــم فقــد‬\n     ‫صــدر احلكــم علــى املدعــى عليهــا بــأن تســلم للمدعــى املبلــغ املدعــى‬\n     ‫بــه ‪ ،‬قــرر ناظــر القضيــة أن احلكــم يف حــق املدعــى عليهــا حضــوري‬\n     ‫وبعــث نســخة مــن الصــك للمدعــى عليهــا حســب التعليمــات ‪ ،‬مت تســليم‬\n     ‫صــورة الصــك للمدعــى عليهــا ورفضــت التوقيــع ‪ ،‬صــدر قــرار محكمــة‬\n                       ‫االســتئناف مبكــة املكرمــة باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n     ‫‪ .......‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة‬\n     ‫احملالــة لنــا مــن فضيلــة رئيس احملكمة العامة مبحافظة جدة‪/‬املســاعد‬\n     ‫برقــم ‪ 33581048‬وتاريــخ ‪1433/09/19‬ه ـ املقيــدة باحملكمــة برقــم‬\n     ‫‪ 331727907‬وتاريخ ‪1433/09/19‬هـ حضر ســعودي اجلنســية مبوجب‬\n     ‫الســجل املدنــي رقــم ولــم حتضــر املدعــى عليهــا وال مــن ينــوب عنها وقد‬\n     ‫تبلغــت باملوعــد فادعــى قائــا يف دعــواه لقــد اقترضــت املدعــى عليهــا‬\n     ‫مــن املدعــو ‪ .....‬مبلغــا وقــدره مائتــا ألــف ريــال وقــد ضمنتهــا يف املبلــغ‬\n     ‫ولــم تســدد املدعــي عليهــا املبلــغ وال شــيئا منــه للمدعــو ‪ .....‬فطالبنــي‬\n\n‫‪73‬‬\n\f‫باملبلــغ فدفعتــه لــه كامــا اطلــب إلــزام املدعــى عليهــا بــأن تدفــع لــي‬\n‫مبلغــا وقــدره مائتــا ألــف ريــال هــذه دعــواي فجــرى ســؤاله هــل لديــه بينــة‬\n‫تثبــت صحــة دعــواه فقــال نعــم ومســتعد بإحضارهــا يف اجللســة القادمــة‬\n‫ويف جلســة أخــرى حضــر املدعــي ولــم حتضــر املدعــى عليهــا وال مــن‬\n‫ينــوب عنهــا وقــد تبلغــت باملوعــد وبســؤال املدعــي عــن البينــة التــي وعــد‬\n‫بإحضارهــا أبــرز ســندا وباالطــاع عليــه وجــد فيــه مــا نصــه ( أقــر أنــا‬\n‫‪ /‬ســعودية اجلنســية قــد إقترضــت مبلــغ وقــدره مائتــان ألــف ريــال نقــدا‬\n‫مــن الســيد ‪ /‬ســعودي اجلنســية قرضــة حســنة تــرد حــن الطلــب وســوف‬\n‫أقــوم بســداد املبلــغ املذكــور وقــدره مائتــان ألــف ريــال ســعودي بتاريــخ‬\n‫‪1429/09/03‬ه ـ وذلــك ألجــل الذهــب توقيــع الشــاهد توقيــع كفيــل‬\n‫غــرم وأداء توقيــع شــاهد توقيــع الشــاهد توقيــع ) وبســؤاله هــل لديــه‬\n‫زيــادة بينــة قــال نعــم لــدي شــهود الســند ومســتعد بإحضارهــم يف اجللســة‬\n‫القادمــة ويف جلســة أخــرى حضــر املدعــي ولــم حتضــر املدعــى عليهــا‬\n‫وال مــن ينــوب عنهــا وقــد تبلغــت باملوعــد مبوجــب محضــر التبليــغ رقــم‬\n‫‪( 34681257‬بــدون تاريــخ) كمــا تبلغــت املدعــى عليهــا مبوعــد اجللســة‬\n‫املنعقــدة بتاريــخ ‪1434/05/12‬ه ـ مبوجــب محضــر التبليــغ (بــدون رقــم‬\n‫وال تاريــخ) املرفــق يف املعاملــة كمــا تبلغــت مبوعــد اجللســة املنعقــدة‬\n‫بتاريــخ ‪1434/07/11‬ه ـ مبوجــب محضــر التبليــغ رقــم ‪ 341508010‬يف‬\n‫‪1434/06/21‬ه ـ املرفــق يف املعاملــة وبســؤال املدعــي عــن البينــة التــي‬\n‫وعــد بإحضارهــا أبــرز ســندا وباالطــاع عليــه وجــد فيــه مــا نصــه ( بســم‬\n‫اهلل الرحمــن الرحيــم إقــرار باســتالم مبلــغ (‪ )200.000‬مئتــا ألــف ريــال‬\n‫بهــذا أقــر‪ .....‬أنــا ســجل مدنــي رقــم ( ) بأننــي قــد اســتلمت مــن املكــرم ‪/‬‬\n‫ســجل مدنــي رقــم ( ) ككفيــل غــارم للســيدة ‪ ......‬ســجل مدنــي رقــم ( )‬\n\n\n                                                                                       ‫‪74‬‬\n\f     ‫مبلــغ وقــدره (‪ )200.000‬مئتــا ألــف ريــال ســعودي بعــد أن التــزم بالســداد‬\n     ‫عنهــا يف حــال فشــلها يف الســداد مبوجــب الســند املوقــع وممهــور ببصمــة‬\n     ‫املذكــورة أعــاه وذلــك بعــد أن فشــلت يف ســداد املبلــغ املوضــح بالســند‬\n     ‫املذكــور ‪1429/09/03‬ه ـ رغــم مطالبتــي لهــا طــوال الفتــرة الســابقة‬\n     ‫بالســداد وهــي تقــوم بالتهــرب وإعطائــي الوعــود الكاذبــة فهــذا ممــا‬\n     ‫اطرنــي ملطالبــة كفيلهــا‪ ......‬وقــام بدفــع كامــل املبلــغ عنهــا‪ .‬وبتوقيعــي‬\n     ‫علــى هــذا اإلقــرار ابــرأ ذمــة املكــرم ‪ ......‬مــن أي مطالبــة ماليــة‬\n     ‫بخصــوص هــذا املبلــغ ألي طــرف آخــر‪ ،‬وهــذا اإلقــرار يعتبــر مخالصــة‬\n     ‫نهائيــة ال رجعــة عنهــا يف مواجهتــه ‪ ،‬وبذلــك يحــق لــه املذكــور بعاليــه‬\n     ‫ا ‪ .‬وأذنــت ملــن يشــهد واهلل علــي‬  ‫الرجــوع عليهــا ملطالبتهــا باملبلــغ كامـ ً‬\n     ‫مــا أقــول شــهيد ‪1433/09/02 ...‬ه ـ شــهد بذلــك ســجل مدنــي رقــم ‪......‬‬\n     ‫توقيــع و ســجل مدنــي رقــم ‪ ......‬توقيــع و ســجل مدنــي رقــم ‪ ......‬توقيــع و‬\n     ‫ســجل مدنــي رقــم ‪ ......‬توقيــع) ثــم أحضــر املدعــي للشــهادة مينــي اجلنســية‬\n                                 ‫مبوجــب اإلقامــة رقــم ‪ ......‬وقــرر الشــاهد قائــا ‪.‬‬\n     ‫أشــهد هلل تعالــى أن املدعــى عليهــا قــد اســتلمت مــن املدعــو مبلغــا وقــدره‬\n     ‫مائتــا ألــف ريــال كقــرض حســن وضمنهــا املدعــي يف الثمــن ومت توقيــع‬\n     ‫ســند بحضــوري وهــو الــذي أبــرزه املدعــي يف جلســة ســابقة كمــا قــام‬\n     ‫املدعــي بســداد املبلــغ وقــدره مائتــا ألــف ريــال للمدعــو ومت توقيــع ســند‬\n     ‫بحضــوري وهــو املرصــود نصــه أعــاه هكــذا شــهد كمــا أحضــر‬\n     ‫املدعــي للشــهادة ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وقــرر‬\n     ‫الشــاهد ‪ .....‬قائــا أشــهد هلل تعالــى أن املدعيــة قــد اســتلمت مــن املدعــو‬\n     ‫‪ .....‬مبلغــا وقــدره مائتــا ألــف ريــال كقــرض حســن وضمنهــا املدعــي يف‬\n     ‫الثمــن ومت توقيــع ســند بحضــوري وهــو الــذي أبــرزه املدعــي يف جلســة‬\n\n\n‫‪75‬‬\n\f‫ســابقة كمــا قــام املدعــي بســداد املبلــغ وقــدره مائتــا ألــف ريــال للمدعــو‬\n‫‪ .....‬ومت توقيــع ســند بحضــوري وهــو املرصــود نصــه أعــاه هكــذا شــهد‬\n‫فجــرى ســؤال املدعــي هــل لديــه زيــادة بينــة فقــال أكتفــي مبــا قدمتــه‬\n‫هكــذا قــرر فطلبــت منــه إحضــار معدلــن لشــاهديه فاســتعد ويف‬\n‫جلســة أخــرى حضــر املدعــي ولــم حتضــر املدعــى عليهــا وال مــن ينــوب‬\n‫عنهــا وبســؤال املدعــي عمــا اســتمهل ألجلــه أحضر ‪ .....‬ســعودي بالســجل‬\n‫املدنــي رقــم ‪ ......‬وقــرر علــي قائــا أشــهد هلل تعالــى أن الشــاهدين عدالن‬\n‫ثقتــان هكــذا شــهد كمــا أحضــر ســعودي بالســجل املدنــي رقــم وقــرر‬\n‫قائــا أشــهد هلل تعالــى أن الشــاهدين عــدالن ثقتــان هكــذا شــهد ثــم‬\n‫عرضــت علــى املدعــي أن يحلــف اليمــن التــي هــذا نصهــا واهلل الــذي ال‬\n‫إلــه إال هــو وال رب ســواه لقــد اقترضــت املدعــى عليهــا مــن املدعــو‪......‬‬\n‫مبلغــا وقــدره مائتــا ألــف ريــال وقــد ضمنتهــا يف املبلــغ وقمــت بتســديد‬\n‫املبلــغ كامــا للمدعــو بعــد أن طالبنــي بــه ولــم تســدد لــي املدعــى عليهــا‬\n‫هــذا املبلــغ وال شــيئا منــه واهلل العظيــم وجــرى وعظــه وتخويفــه مــن‬\n‫عاقبــة اليمــن الكاذبــة فاســتعد ببذلهــا ثــم حلــف قائــا واهلل الــذي ال‬\n‫إلــه إال هــو وال رب ســواه لقــد اقترضــت املدعــى عليهــا ‪ ......‬مــن املدعــو‬\n‫‪ .....‬مبلغــا وقــدره مائتــا ألــف ريــال وقــد ضمنتهــا يف املبلــغ وقمــت بتســديد‬\n‫املبلــغ كامــا للمدعــو ‪ .....‬بعــد أن طالبنــي بــه ولــم تســدد لــي املدعــى‬\n‫عليهــا هــذا املبلــغ وال شــيئا منــه واهلل العظيــم هكــذا حلــف فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى وشــهادة الشــاهدين املعدلــن شــرعا ومــا تضمنتــه‬\n‫الســندات التــي أبرزهــا املدعــي واليمــن التــي بذلهــا وألن امتنــاع املدعــى‬\n‫عليهــا عــن حضــور ثــاث جلســات رغــم تبلغهــا بهــا وعــدم تقدميهــا عــذرا‬\n‫عــن عــدم احلضــور رغــم تباعــد مواعيد هذه اجللســات يعد نكوال وقرينة‬\n\n\n                                                                                        ‫‪76‬‬\n\f     ‫تضعــف جانبهــا وتقــوي جانــب املدعــي وألن اليمــن تشــرع يف جنبــة أقــوى‬\n     ‫املتداعيــن وجانــب املدعــي واحلــال مــا ذكــر أقــوى واســتنادا للمــادة‬\n     ‫اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية ولوائحهــا التنفيذيــة‬\n     ‫لذلــك كلــه فقــد حكمــت علــى املدعى عليها ســعودية اجلنســية مبوجب‬\n     ‫الســجل املدنــي رقــم بــأن تدفــع للمدعــي مبلغــا وقــدره مائتــا ألــف ريــال‬\n     ‫ويعــد حكمــي هــذا يف حــق املدعــى عليهــا حضوريــا وقــررت بعــث‬\n     ‫نســخة مــن احلكــم للمدعــى عليهــا عــن طريــق اجلهــة املختصــة لتســليمها‬\n     ‫وذلــك لتقــدمي الالئحــة اإلعتراضيــة خــال ثالثــن يومـ ًا مــن إســتالمها لــه‬\n     ‫إن أرادت وتفهــم بأنــه إن مضــت املــدة احملــددة لإلعتــراض ولــم تتقــدم‬\n     ‫بالالئحــة اإلعتراضيــة فــإن حقهــا يســقط يف طلــب االســتئناف ويصبــح‬\n     ‫احلكــم مكتســب ًا القطعيــة ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/08/10‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف‬\n     ‫يــوم األحــد املوافــق ‪ 1434/10/25‬ه ـ افتتحــت اجللســة بعــد أن وردنــا‬\n     ‫خطــاب مديــر شــرطة الشــمالية مبحافظــة جــدة برقــم ‪ 6/12532‬يف‬\n     ‫‪1434/09/17‬ه ـ املتضمــن(مت تســليم صــورة صــك احلكــم عــن طريــق‬\n     ‫منــدوب العمــدة ورفضــت التوقيــع) بنــاء علــى ذلــك ومبــا أن املــادة ‪5/176‬‬\n     ‫مــن الالئحــة التنفيذيــة لنظــام املرافعــات الشــرعية تنــص علــى أنــه إذا‬\n     ‫تعــذر تســليم نســخة احلكــم الغيابــي للمحكــوم عليــه أو وكيلــه فإنــه‬\n     ‫يرفــع حملكمــة التمييــز بــدون الئحــة إعتراضيــه لــذا فقــد قــررت إرســال‬\n     ‫املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم حســب التعليمــات ‪،‬‬\n     ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪1434/10/25‬ه ـ‬\n\n\n‫‪77‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد ففــي‬\n‫يــوم الثالثــاء املوافــق ‪ 1434/12/17‬ه ـ افتتحــت اجللســة وقــد عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪ 34356175‬يف‬\n‫‪1434/11/10‬ه ـ ونــص احلاجــة منــه (وبدراســة احلكــم وصــورة ضبطــه‬\n‫تقــررت املوافقــة علــى احلكــم ‪ ،‬قاضــي اســتئناف ختــم وتوقيــع قاضــي‬\n‫اســتئناف ختــم وتوقيــع رئيــس الدائــرة ختــم وتوقيــع )عليــه فقــد أمــرت‬\n‫بإثباتــه علــى ضبطــه وســجله حتــى ال يخفــى ‪ ،‬وبــاهلل التوفيــق وصلى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/12/17‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبحافظــة جــدة برقــم ‪331727907‬‬\n‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ القاضــي باحملكمــة‬\n‫العامــة بجــدة واملســجل بعــدد ‪ 34293933‬وتاريــخ ‪1434/8/10‬هـ ـ‬\n‫واملتضمــن دعــوى‪ ......‬ضــد‪ ......‬واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم واهلل‬\n      ‫املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                   ‫‪78‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":72,"source_page_end":78,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"86e3ce97c70437f3b8eeeadf2823e361d93bc9160ee23e23414718ca23c32160","normalized_text_hash":"0cdcec9056c7fea683759b78a9546e6db2ff5372042c028f5d2c1690b09f04bf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p72-34293933"},{"id":"4cb0c047-a938-5112-b700-4e50ec67dd3d","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -عقد بيع -مطالبة بدين مورث -دعوى من بعض الورثة دون بعض -ادعاء السداد -بينة غير موصلة -توجيه ميني للمدعى البالغ بنفي العلم عن سداد دين ملورثه -رد املدعى اليمن على املدعى عليه -أداء املدعى عليه اليمن يف حق احد املدعن دون غيره -دعوى على قاصر بالسداد -عدم النيابة يف اليمن -شبهة تقتضى تأجيل احلكم -تأجيل مين على قاصر حتى تكليفه -قرار بالتوقف عن حكم يف نصيب قاصر حتى تكليفه لعرض اليمن","document_number":"34275262","case_number":"33705143","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/22","year":"1434","subject":"قرض -عقد بيع -مطالبة بدين مورث -دعوى من بعض الورثة دون بعض -ادعاء السداد -بينة غير موصلة -توجيه ميني للمدعى البالغ بنفي العلم عن سداد دين ملورثه -رد املدعى اليمن على املدعى عليه -أداء املدعى عليه اليمن يف حق احد املدعن دون غيره -دعوى على قاصر بالسداد -عدم النيابة يف اليمن -شبهة تقتضى تأجيل احلكم -تأجيل مين على قاصر حتى تكليفه -قرار بالتوقف عن حكم يف نصيب قاصر حتى تكليفه لعرض اليمن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/7/22 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34275262 :‬‬\n                        ‫َر ْق ُم الدعوى‪33705143 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34308669‬تاريخه‪1434/8/29 :‬هـ‬\n\n\n\n     ‫قــرض ‪ -‬عقــد بيــع ‪ -‬مطالبــة بديــن مــورث ‪ -‬دعــوى مــن بعــض الورثــة‬\n     ‫دون بعــض ‪ -‬ادعــاء الســداد ‪ -‬بينــة غيــر موصلــة ‪ -‬توجيه ميني للمدعى‬\n     ‫البالــغ بنفــي العلــم عــن ســداد ديــن ملورثــه ‪ -‬رد املدعــى اليمــن علــى‬\n     ‫املدعــى عليــه ‪ -‬أداء املدعــى عليــه اليمــن يف حــق احــد املدعــن دون‬\n     ‫غيــره ‪ -‬دعــوى علــى قاصــر بالســداد ‪ -‬عــدم النيابــة يف اليمــن ‪ -‬شــبهة‬\n     ‫تقتضــى تأجيــل احلكــم ‪ -‬تأجيــل ميــن علــى قاصــر حتــى تكليفه ‪ -‬قرار‬\n     ‫بالتوقــف عــن حكــم يف نصيــب قاصــر حتــى تكليفــه لعــرض اليمــن‬\n     ‫عليــه ‪ -‬رد دعــوى ‪ -‬إلــزام بدفــع مبلــغ الديــن للورثــة ‪ -‬ســداد مبلــغ‬\n     ‫محكــوم بــه ‪ -‬حكــم واجــب االســتئناف لعــدم احلكــم للقاصــر بجميــع‬\n                                                                        ‫طلباتــه ‪.‬‬\n\n\n\n\n     ‫قــال يف كشــاف القنــاع (‪« )451/6‬وال تدخــل النيابــة يف اليمــن فــا‬\n     ‫يحلــف احــد عــن غيــره فلــوكان املدعــى عليــه صغيــرا أو مجنونــا لــم‬\n                ‫يحلــف ألنــه ال يعــول علــى قولــه ووقــف األمــر إلــى أن يكلفــا»‬\n\n\n\n\n‫‪79‬‬\n\f‫دعــوى املدعــي بالوكالــة واملوكلــة أصالــة عــن نفســها وبصفتهــا وليــة‬\n‫علــى ابنهــا القاصــر ضــد املدعــى عليــه ومضمــون الدعــوى أنــه توفــى‬\n‫مــورث املوكلــة وابنهــا وانحصــر ورثتــه يف والــده ويف زوجته املدعية وفى‬\n‫ابنهــا القاصــر الــذي هــو حتــت واليــة والدتــه وأنــه يوجــد بذمــة املدعــى‬\n‫عليــه ملــورث املدعيــة وابنهــا مبلغــا قــدره ســتة وســتون ألف ـ ًا وخمســمائة‬\n‫ريــال قرضــا وكذلــك مبلغــا قــدره واحــد وســتون ألــف ريــال ثمــن ســيارة‬\n‫اشــتراها املدعــى عليــه مــن مــورث املدعيــة وابنهــا وأن املدعــى عليــه لــم‬\n‫يســددها ويطالــب املدعــي وكالــة إلــزام املدعــى عليــه بتســليم نصيــب‬\n‫املدعيــة مبلغــا وقــدره خمســة عشــر ألفــا وتســعمائة وســبعة وثالثــون‬\n‫ريــا ًال وخمســون هللــة‪ ،‬ونصيــب ابنهــا القاصــر مبلغــا قــدره تســعون‬\n‫ألفــا وثالثمائــة واثنــا عشــر ريــا ًال وخمســون هللــة‪ .‬ومبواجهــة املدعــى‬\n‫عليــه صــادق علــى الدعــوى وقــرر أنــه ســدد مــن القــرض للمتوفــى حــال‬\n‫حياتــه جــزء ًا مــن املبلــغ ولــم يقــدم بينــة موصلــة علــى ذلــك وطلــب ميــن‬\n‫املدعيــة ورفضــت املدعيــة أداء اليمــن وطلبــت ميينــه وقــام بــأداء اليمــن‬\n‫وعليــه قــررت احملكمــة االعتــداد بيمينــه فيمــا يخــص حــق الزوجــة دون‬\n‫القاصــر وتأجيــل اليمــن يف حــق القاصــر حلــن تكليفــه وإلــزام املدعــى‬\n‫عليــه بســداد باقــي نصيــب األم وقــرر الطرفــان القناعــة وجــرى إرســال‬\n ‫األوراق حملكمــة االســتئناف لوجــود قاصــر وجــرى تصديــق احلكــم‪.‬‬\n\n\n\n\n                                                                                      ‫‪80‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة العامــة‬\n     ‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن الرئيــس برقــم ‪33705143‬‬\n     ‫يف ‪ 1433/12/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332245175‬يف‬\n     ‫‪ 1433/12/26‬ه ـ حضــر ‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫ا عــن ‪ ......‬أصالــة عــن نفســها وبصفتهــا وليــة‬    ‫رقــم ‪ ......‬بصفتــه وكي ـ ً‬\n     ‫علــى ابنهــا املولــود يف ‪1432/5/27‬ه ـ مبوجــب صــك الواليــة رقــم‬\n     ‫‪ 32153272‬يف ‪1432/7/3‬ه ـ الصــادر مــن محكمــة عنيــزة وذلــك‬\n     ‫مبوجــب الوكالــة رقــم ‪ 33343716‬يف ‪1433/7/15‬ه ـ الصــادرة مــن‬\n     ‫كتابــة عــدل عنيــزة وادعــى علــى احلاضــر معــه ‪ ......‬ســعودي اجلنســية‬\n     ‫ا يف دعــواه إنــه بتاريــخ ‪1432/6/17‬هـ‬      ‫مبوجــب الســجل املدنــي رقــم قائـ ً‬\n     ‫توفــى ‪ ......‬وهــو مــورث موكلــي املذكوريــن وانحصــر ورثتــه يف والــده‬\n     ‫وزوجتــه وابنــه القاصــر مبوجــب صــك حصــر الورثــة رقــم ‪32152337‬‬\n     ‫يف ‪1432/7/3‬ه ـ الصــادر مــن محكمــة عنيــزة ويوجــد بذمــة املدعــى‬\n     ‫عليــه ملــورث موك ّلــي املذكــور مبلــغ وقــدره ‪ 66500‬ســتة وســتون‬\n     ‫ألفــا وخمســمائة ريــال قرضــا وكذلــك مبلــغ وقــدره ‪ 61000‬واحــد‬\n     ‫وســتون ألــف ريــال قيمــة ســيارة ‪ ......‬موديــل ‪ 2002‬م اشــتراها املدعــى‬\n     ‫عليــه مــن املتوفــى املذكــور وإجمالــي املبلــغ الــذي بذمــة املدعــى عليــه‬\n     ‫ملــورث موك ّلــي ‪ 127500‬مائــة وســبعة وعشــرون ألــف وخمســمائة ريــال‬\n     ‫لــم يســدد املدعــى عليــه منهــا شــيئا للمتوفــى حــال حياتــه ولــم يســلم‬\n     ‫ملوك ّلــي شــيئا مــن نصيبهــم منهــا بعــد وفــاة مورثهــم أطلــب احلكــم علــى‬\n     ‫املدعــى عليــه بدفــع نصيــب موكلتــي زوجــة املتوفــى مــن املبلــغ املذكــور‬\n\n‫‪81‬‬\n\f‫وقــدره خمســة عشــر ألفــا وتســعمائة وســبعة وثالثــون ريــاال وخمســون‬\n‫هللــة ونصيــب ابنهــا املذكــور الــذي حتــت واليتهــا وقــدره تســعون ألفــا‬\n‫وثالثمائــة واثنــا عشــر ريــاال وخمســون هللــة هذه دعواي وبســؤال املدعى‬\n‫عليــه عــن دعــوى املدعــي وكالــة أجــاب بقولــه مــا ذكــره املدعــي مــن أن‬\n‫مــورث موكليــه املذكوريــن قــد تــويف وانحصــر ورثتــه يف املذكوريــن‬\n‫وأننــي اقترضــت مــن مورثهــم حــال حياتــه ســتة وســتني ألفــا وخمســمائة‬\n‫ريــال وأننــي اشــتريت الســيارة املذكــورة مــن املتوفــى املذكــور بواحــد‬\n‫وســتني ألــف ريــال فهــذا صحيــح ولكننــي ســددت مــن القــرض للمتوفــى‬\n‫حــال حياتــه ألفــن وثمامنائــة وخمســن ريــاال وســددت قيمــة الســيارة‬\n‫للمتوفــى كاملــة حــال حياتــه حيــث كانــت علــى أقســاط ولــم يبــق علــي‬\n‫مــن قيمتهــا شــيء وكان شــرائي للســيارة قبــل ثمــان ســنوات هكــذا‬\n‫أجــاب املدعــى عليــه وبعــرض جــواب املدعــى عليــه علــى املدعــي وكالــة‬\n‫قــال ال صحــة ملــا جــاء يف جــواب املدعــى عليــه مــن ســداده لقيمة الســيارة‬\n‫وجــزء مــن قيمــة القــرض هكــذا أجــاب املدعــي وكالة وبســؤال املدعى‬\n‫عليــه عــن بينتــه علــى الســداد قــال ال أعلــم لــي بينــة ويف جلســة أخــرى‬\n‫حضــر املدعــي وكالــة واملدعــى عليــه وقــرر املدعــى عليــه بقولــه إننــي‬\n‫وجــدت بينــة وأطلــب املهلــة إلحضارهــا ولذلــك فقــد أمهلــت املدعــى‬\n‫عليــه إلحضارهــا ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى‬\n‫عليــه وبســؤال املدعــى عليــه عــن البينــة التــي وعــد بإحضارهــا يف اجللســة‬\n‫الســابقة أحضــر ‪ ....‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫املعــرف بهــا مــن قبــل ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫وبســؤالها عمــا لديهــا مــن شــهادة قالــت أشــهد بــأن أخــي قــد أخبرنــي‬\n‫قبــل وفاتــه بأنــه قــد اســتلم قيمــة الســيارة ‪ ....‬كاملــة مــن أخــي املدعــى‬\n\n\n                                                                                      ‫‪82‬‬\n\f     ‫عليــه وقــال لــي أخــي املتوفــى إننــا خلصنــا مــن قيمــة الســيارة ونفــس هــذا‬\n     ‫الــكالم ســمعته مــن زوجتــه الســابقة ‪ ......‬ســورية اجلنســية هــذا مــا لــدي‬\n     ‫مــن شــهادة هكــذا شــهدت الشــاهدة وبعــرض الشــاهدة والشــهادة علــى‬\n     ‫املدعــي وكالــة قــال ال أعــرف املدعيــة وال أطعــن فيهــا والشــهادة ال أعلــم‬\n     ‫عنهــا هكــذا قــرر فســألت املدعــى عليــه هــل لديــه زيــادة بينــة فقــال‬\n     ‫نعــم وأطلــب املهلــة إلحضارهــا فأمهلتــه ويف جلســة أخــرى حضــر املدعــي‬\n     ‫وكالــة واملدعــى عليــه وأحضــر املدعــى عليــه معــه الشــاهد ‪ ....‬ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ......‬وبســؤال الشــاهد عن شــهادته‬\n     ‫قــال أشــهد بأننــي كنــت جالســا مــع والــدي واملدعــى عليــه وقــد قــال‬\n     ‫املدعــى عليــه لوالــدي إن الديــن الــذي بينــي أنــا وأخــي يف الســيارة‪.........‬‬\n     ‫قــد انتهــى وســددته كامــل املبلــغ هكــذا قــال املدعــى عليــه ولــم‬\n     ‫يكــن معنــا حــن قــال املدعــى عليــه هــذا الــكالم كمــا أننــي كنــت‬\n     ‫أشــاهد أوراقــا علــى طاولــة املدعــى عليــه تتضمــن اإلشــارة إلــى ديــن ال‬\n     ‫أذكــر تفاصيلــه وعليهــا توقيــع مــورث املدعــن هــذا مــا اذكــره هــذا‬\n     ‫مــا لــدي مــن شــهادة وبعــرض الشــاهد والشــهادة علــى املدعــي وكالــة‬\n     ‫قــال ال أعــرف الشــاهد وال أطعــن فيــه وأمــا مــا جــاء يف شــهادته فهــو‬\n     ‫غيــر موصــل كمــا أنــه لــم يشــهد بالســماع مــن مــورث موكلــي هكــذا‬\n     ‫أجــاب املدعــي وكالــة وقــد ســألت املدعــى عليــه هــل لديــك زيــادة بينــة‬\n     ‫فقــال أطلــب املهلــة لذلــك فأمهلتــه ويف جلســة أخــرى حضــر املدعــي‬\n     ‫وكالــة واملدعــى عليــه وقــد ســألت املدعــى عليــه هــل لديــه زيــادة بينــة‬\n     ‫فقــال ال أعلــم لــي زيــادة بينــة هكــذا قــرر وقــد اطلعــت علــى صــك حصــر‬\n     ‫الورثــة ووكالــة املدعــي فوجدتهــا كمــا ذكــر فبنــاء علــى مــا تقــدم مــن‬\n     ‫دعــوى املدعــي وكالــة املتضمنــة أن بذمــة املدعــى عليــه ملــورث موكليــه‬\n\n\n‫‪83‬‬\n\f‫‪127500‬مائــة وســبعة وعشــرون ألــف وخمســمائة ريــال لــم يســدد منهــا‬\n‫شــيئا وطلبــه احلكــم علــى املدعــى عليــه بدفــع نصيــب موكلتــه ونصيــب‬\n‫ابنهــا املذكــور الــذي حتــت واليتهــا مــن هــذا املبلــغ وإلقــرار املدعــى‬\n‫عليــه بأصــل اســتحقاق املبلــغ املدعــى بــه يف ذمتــه ودفعــه بأنــه ســدد‬\n‫جــزءا مــن القــرض وأنــه ســدد قيمــة الســيارة للمتوفــى كاملــة حــال‬\n‫حياتــه وإلنــكار املدعــي وكالــة ملــا دفــع بــه املدعــى عليــه ونظــرا إلــى‬\n‫أن املدعــى عليــه لــم يحضــر بينــة موصلــة ملــا دفــع بــه فشــهادة الشــاهدة ال‬\n‫تكفــي لوحدهــا وشــهادة الشــاهد الــذي أحضــره غيــر موصلــة ولذلــك‬\n‫فقــد أفهمــت املدعــى عليــه بــأن اليمــن تتوجــه علــى املدعــن علــى نفــي‬\n‫علمهــم بســداده لقيمــة الســيارة ومبلــغ ألفــن وثمامنائــة وخمســن ريــاال‬\n‫مــن القــرض فقــال أطلــب ميينهــم علــى ذلــك وبســؤال املدعــي وكالــة هــل‬\n‫موكلتــه مســتعدة باليمــن فيمــا يخصهــا دون مــا يخــص ابنهــا القاصــر‬\n‫قــال إن موكلتــي لــن حتلــف وتطلــب ميــن املدعــى عليــه فيمــا يخصهــا‬\n‫مــن املبلــغ علــى أنــه ســلم مــن القــرض مبلــغ ألفــن وثمامنائــة وخمســن‬\n‫ريــال ‪ 2850‬وأنــه ســدد قيمــة الســيارة كاملــة فــإذا حلــف فإنهــا ترضــى‬\n‫بيمينــه فيمــا يخصهــا وتطلــب احلكــم عليــه بدفــع مــا يخصهــا بعد خصم‬\n‫مــا يحلــف علــى ســداده وإجــراء املقتضــى الشــرعي نحــو حــق القاصــر‬\n‫هكــذا قــرر املدعــي وكالــة ولكــون املدعــي وكالــة مخــول بطلــب‬\n‫اليمــن وردهــا فقــد عرضــت ذلــك علــى املدعــى عليــه فقرر بقولــه ال مانع‬\n‫لــدي مــن اليمــن حلــق املدعيــة هكــذا قــرر املدعــى عليــه وبطلــب اليمــن‬\n‫مــن املدعــى عليــه حلــف قائــا واهلل العظيــم إننــي ســددت قيمــة الســيارة‬\n‫املذكــورة وقدرهــا واحــد وســتون ألــف ريــال كاملــة ألخــي املتــويف حــال‬\n‫حياتــه وســددت لــه مــن قيمــة القــرض ألفــن وثمامنائــة وخمســن ريــال‬\n\n\n                                                                                       ‫‪84‬‬\n\f     ‫هكــذا حلــف املدعــى عليــه فبنــاء علــى مــا تقــدم ولتوجــه اليمــن علــى‬\n     ‫املدعــن ورد املدعــي وكالــة اليمــن علــى املدعــى عليــه فيمــا يخصهــا‬\n     ‫مــن املبلــغ املدعــى بــه وأداء املدعــى عليــه اليمــن للمدعيــة ونظــرا إلــى‬\n     ‫أن القاصــر هنــا مدعــى عليــه يف الســداد وقــد قــال يف كشــاف القنــاع‬\n     ‫(‪( :)451/6‬وال تدخــل النيابــة يف اليمــن فــا يحلــف أحــد عــن غيــره‬\n     ‫فلــو كان املدعــى عليــه صغيــرا أو مجنونــا لــم يحلــف ألنــه ال يعــول علــى‬\n     ‫قولــه ووقــف األمــر إلــى أن يكلفــا) انتهــى وملــا تقــدم كلــه ولوجــود‬\n     ‫شــبهة تقتضــي تأجيــل احلكــم يف حــق القاصــر الــذي ادعــى املدعــى‬\n     ‫عليــه ســداده ألن علــى القاصــر ميينــا مؤجلــة إلــى تكليفــه وقــد ينــكل‬\n     ‫عنهــا أو يردهــا ولشــهادة املــرأة ورد والدتــه اليمــن علــى املدعــى عليــه‬\n     ‫فقــد قــررت التوقــف عــن احلكــم يف نصيــب القاصــر مــن قيمــة الســيارة‬\n     ‫املذكــورة وعــن احلكــم يف نصيــب القاصــر مــن مبلــغ ألفــن وثمامنائــة‬\n     ‫وخمســن ريــاال التــي ادعــى املدعــى عليــه ســدادها مــن القــرض حتــى‬\n     ‫يكلــف القاصــر لعــرض اليمــن عليــه ورددت دعــوى املدعيــة يف نصيبهــا‬\n     ‫مــن قيمــة الســيارة ومــن مبلــغ ألفــن وثمامنائــة وخمســن ريــاال التــي‬\n     ‫ادعــى املدعــى عليــه ســدادها مــن القــرض وألزمــت املدعــى عليــه بدفــع‬\n     ‫نصيــب املدعيــة وابنهــا القاصــر مــن الباقــي مــن القــرض وقــدره ثالثــة‬\n     ‫وســتون ألفــا وســتمائة وخمســون ريــاال للمدعيــة ســبعة آالف وتســعمائة‬\n     ‫وســتة وخمســون ريــاال وخمــس وعشــرون هللــة والبنهــا القاصــر خمســة‬\n     ‫وأربعــون ألفــا وخمســة وثمانــون ريــاال وإحــدى وأربعــون هللــة وبجميــع مــا‬\n     ‫تقــدم حكمــت وبعــرض احلكــم علــى الطرفــن قــررا القناعــة بــه وقــد‬\n     ‫أفهمــت الطرفــن أن احلكــم واجــب االســتئناف ألنــه لــم يحكم للقاصر‬\n     ‫بجميــع طلباتــه وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n\n\n‫‪85‬‬\n\f                                                ‫‪ .‬حــرر يف ‪ 1434/07/22‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بعنيــزة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بعنيــزة برقــم ‪ 33705143‬وتاريــخ ‪1433/12/26‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 332245175‬وتاريــخ ‪1433/12/26‬ه ـ ففــي يــوم األحــد‬\n‫املوافق‪1434/09/13‬ه ـ افتتحــت اجللســة الســاعة الثانيــة والربــع ظهــرا‬\n‫وقــد عــادت إلينــا املعاملــة مــن محكمــة االســتئناف بالقصيــم برقــم‬\n‫‪ 342027960‬يف ‪1434/ 9/ 6‬ه ـ وبرفقهــا قــرار محكمــة االســتئناف‬\n‫بالقصيــم رقــم ‪ 34308669‬يف ‪1434/ 8 / 29‬ه ـ املتضمــن املصادقــة‬\n‫علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                               ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/09/13‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي املــازم القضائــي لــدى فضيلــة الشــيخ‬\n‫القاضــي يف احملكمــة العامــة بعنيــزة وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بعنيــزة برقــم ‪33705143‬‬\n‫وتاريــخ ‪1433/12/26‬ه ـ املقيــدة باحملكمــة برقــم ‪332245175‬‬\n‫وتاريــخ ‪ 1433/12/26‬ه ـ ففــي يــوم اإلثنــن املوافــق ‪1434/10/12‬‬\n‫ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة ســعودي بالســجل رقــم‬\n‫بصفتــه وكيــا عــن ‪ /‬أصالــة عــن نفســها وبصفتهــا وليــة علــى ابنهــا‬\n‫املولــود يف ‪1432/5/27‬ه ـ مبوجــب صــك الواليــة رقــم ‪ 32153272‬يف‬\n‫‪1432/7/3‬ه ـ الصــادر مــن محكمــة عنيــزة وذلــك مبوجــب الوكالــة‬\n‫رقــم ‪ 333433716‬يف ‪1433/7/15‬ه ـ الصــادرة مــن كتابــة عــدل‬\n‫عنيــزة املخــول لــه فيهــا باالســتالم وقــرر بقولــه إننــي اســتلمت كامــل‬\n‫املبلــغ احملكــوم بــه ملوكلتــي وموليهــا القاصــر يف الصــك الصــادر‬\n\n\n                                                                                   ‫‪86‬‬\n\f     ‫برقــم ‪ 34275262‬يف ‪1434/7/22‬ه ـ مبوجــب الشــيك رقــم ‪ 94‬يف‬\n     ‫‪2013/8/19‬م املســحوب علــى مصــرف الراجحــي مببلــغ قــدره ســبعة‬\n     ‫آالف وتســعمائة وســتة وخمســون ريــاال وخمــس وعشــرون هللــة ومبوجــب‬\n     ‫الشــيك رقــم ‪ 93‬يف ‪2013/8/19‬م املســحوب علــى مصــرف الراجحــي‬\n     ‫وقــدره خمســة وأربعــون ألــف وخمــس وثمانــون ريــاال وواحــد وأربعــون‬\n     ‫هللــة هكــذا قــرر وبذلــك يكــون املدعــي وكالــة قــد اســتلم كامــل‬\n     ‫املبلــغ احملكــوم بــه يف هــذا الصــك وجــرى إحلاقــه حتــى ال يخفــى وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                          ‫حــرر يف ‪ 1434/10/12‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n     ‫الثانيــة مبحكمــة االســتئناف مبنطقــة القصيــم على املعاملــة الواردة من‬\n     ‫فضيلــة رئيــس احملكمــة العامــة مبحافظــة عنيــزة برقــم (‪)332245175‬‬\n     ‫وتاريــخ ‪ 1434/8/16‬هــ؛ اخلاصــة بدعــوى ع بالوكالــة عــن أصالــة عــن‬\n     ‫نفســها وواليــة علــى ابنهــا ؛ ضــد بشــأن املطالبــة مببلــغ مالــي ؛ املرفــق بهــا‬\n     ‫الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ املســجل برقــم‬\n     ‫(‪ )34275262‬وتاريــخ ‪1434/7/22‬هــ؛ املتضمــن أنــه قــرر التوقــف عــن‬\n     ‫احلكــم يف نصيــب القاصــر مــن قيمــة الســيارة املذكــورة وعــن احلكــم‬\n     ‫يف نصيــب القاصــر مــن مبلــغ ألفــن وثمامنائــة وخمســن ريــا ًال التــي ادعــى‬\n     ‫املدعــى عليــه ســدادها مــن القــرض حتــى يكلــف القاصــر لعــرض‬\n     ‫اليمــن عليــه ور َّد دعــوى املدعيــة يف نصيبهــا مــن قيمــة الســيارة ومــن‬\n     ‫مبلــغ األلفــن وخمســمائة ريــال وألــزم املدعــى عليــه بدفع نصيــب املدعية‬\n     ‫وابنهــا القاصــر مــن باقــي القــرض وقــدره ثالثــة وســتون ألف ـ ًا وســتمائة‬\n     ‫وخمســون ريــا ًال للمدعيــة ســبعة آالف وتســعمائة وســتة وخمســون ريــا ًال‬\n\n\n‫‪87‬‬\n\f‫وخمــس وعشــرون هللــة والبنهــا القاصــر خمســة وأربعــون ألفـ ًا وخمســة‬\n‫وثمانــون ريــا ًال وإحــدى وأربعــون هللــة وبذلــك حكــم؛ كمــا هــو مــدون‬\n‫ومفصــل فيــه؛ وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة؛ قررنــا‪ :‬التصديــق علــى احلكــم‪ .‬واهلل املوفــق؛ وصلــى‬\n                        ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪88‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":79,"source_page_end":88,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"90435c76698d308857d8ca6892834f3e2b2c72466b2309580bdad7513280fa63","normalized_text_hash":"60d57b8aca79e2b138d0370e877ec6063f29cba1bdc9a8e8d2370b828b8a67cf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p79-34275262"},{"id":"b334ecfa-36cf-5358-b6f2-6faa29042009","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -إقراض مبوجب حوالة بنكية -حكم على املدعى عليه بإعادة قرض مع دفعه انه مؤجل .","document_number":"34240537","case_number":"34146443","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/13","year":"1434","subject":"قرض -إقراض مبوجب حوالة بنكية -حكم على املدعى عليه بإعادة قرض مع دفعه انه مؤجل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/6/13 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34240537 :‬‬\n                        ‫َر ْق ُم الدعوى‪34146443 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 34340355‬تاريخه‪1434/10/26 :‬هـ‬\n\n\n\n     ‫قــرض ‪ -‬إقــراض مبوجــب حوالــة بنكيــة ‪ -‬حكــم علــى املدعــى عليــه‬\n                                       ‫بإعــادة قــرض مــع دفعــه انــه مؤجــل ‪.‬‬\n\n\n\n\n     ‫‪ -1‬قــال يف الــروض املربــع ‪ ( 40/5‬بــل يثبــت بدلــه يف ذمتــه أي ذمــة‬\n     ‫املقتــرض حــا ًال ولــو أجلــه املقتــرض ألنــه عقــد منــع فيــه التفاضــل‬\n     ‫فمنــع األجــل فيــه كالصــرف قــال اإلمــام القــرض حــال وينبغــي أن‬\n                                                               ‫يفــي بوعــده ) ‪.‬‬\n                  ‫‪ -2‬قال يف احلاشية ‪ ( 40/5‬ألن الوفاء بالوعد مستحب ) ‪.‬‬\n\n\n\n\n     ‫دعــوى املدعــى وكالــة ضــد املدعــى عليــه بــأن موكلــه قــد أقــرض‬\n     ‫املدعــى عليــه مبلغــا قــدره عشــرون ألــف جنيــه بريطانــي قرضــا حســن ًا‬\n     ‫عــن طريــق حوالــة بنكيــة وطلــب احلكــم علــى املدعــى عليــة بــأن يســلم‬\n     ‫ملوكلــه مبلــغ القــرض‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى‬\n     ‫ودفــع بــأن املدعــي أصالــة أعطــاه مهلــة يف الســداد وأن املهلــة لــم حتــل‪،‬‬\n     ‫أنهــى ناظــر القضيــة حكمــه بأنــه بنــاء علــى إقــرار املدعــى عليــه‬\n     ‫بالدعــوى ولقولــه يف الــروض املربــع « بــل يثبــت بدلــه يف ذمتــه أي ذمــه‬\n\n‫‪89‬‬\n\f‫املقتــرض حــاال ولــو اجلــه املقتــرض ‪ ...‬الــخ‪ ،‬فقــد صــدر احلكــم بإلــزام‬\n‫املدعــى عليــه بــأن يســلم للمدعــى املبلــغ املدعــى بــه ‪ ،‬قــرر املدعــى عليــه‬\n‫عــدم القناعــة ‪ ،‬صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة‬\n                                                     ‫باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي ‪ ....‬يف احملكمــة العامــة‬\n‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة باملدينــة املنــورة املســاعد برقــم ‪34146443‬‬\n‫وتاريــخ ‪1434/03/29‬ه ـ املقيــدة باحملكمــة برقــم ‪34779483‬‬\n‫وتاريــخ ‪ 1434/03/29‬ه ـ ففــي يــوم الثالثــاء املوافــق‪1434/06/13‬‬\n‫ه ـ حضــر‪ ....‬ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم ‪ ....‬بصفتــه‬\n‫الوكيــل الشــرعي عــن ‪ ....‬بريطانــي اجلنســية مبوجــب جــواز الســفر رقــم‬\n‫يف ‪ 2009/3/17‬صــادر مــن لنــدن مبوجــب الوكالــة رقــم ‪34371580‬‬\n‫يف ‪1434/3/25‬ه ـ صــادر مــن كتابــة العــدل باملدينــة املنــورة وادعــى‬\n‫ا يف دعــواه‪:‬‬‫علــى احلاضــر معــه مصــري اجلنســية باإلقامــة رقــم ‪ ....‬قائ ـ ً‬\n‫أقــرض موكلــي املدعــى عليــه مبلغ ـ ًا مقــداره عشــرون ألــف جنيــه‬\n‫بريطانــي (‪ )20000‬قرض ـ ًا حســن ًا يف شــهر ديســمبر ‪2012‬م وذلــك‬\n‫عــن طريــق حوالــة بنكيــة مــن لنــدن إلــى املدينــة املنــورة لذلــك يطالــب‬\n‫موكلــي باحلكــم علــى املدعــى عليــه بتســليمه جميــع مبلــغ القــرض‬\n‫ومقــداره عشــرون ألــف جنيــه بريطانــي حــا ًال هــذه دعــواي ‪ .‬وبســؤال‬\n‫املدعــى عليــه أجــاب قائ ـاً‪ :‬مــا ذكــره املدعــي بالوكالــة يف دعــواه‬\n\n                                                                                       ‫‪90‬‬\n\f     ‫كلــه صحيــح حيــث إنــه يف شــهر ديســمبر ‪2012‬م أقرضنــي موكلــه‬\n     ‫مبلغ ـ ًا مقــداره عشــرون ألــف جنيــه بريطانــي (‪ )20000‬وأعطانــي فيهــا‬\n     ‫مهلــة ســنة تنتهــي يف شــهر ديســمبر ‪2013‬م حيــث أرســلت لــه تعهــد‬\n     ‫باســترجاع هــذا القــرض يف شــهر ديســمبر ‪ 2013‬م عــن طريــق البريــد‬\n     ‫اإللكترونــي واســتلم البريــد وســكت ولــم يــرد ممــا يــدل علــى موافقتــه‬\n     ‫علــى املهلــة ومســتعد بإرجــاع كامــل مبلــغ القــرض ومقــداره عشــرون‬\n     ‫ألــف جنيــه بريطانــي (‪ )20000‬يف شــهر ديســمبر ‪2013‬م هــذا جوابــي‬\n     ‫ـاء علــى مــا تقــدم مــن الدعــوى‬  ‫‪ .‬ثــم إنــه وبعــد التأمــل يف القضيــة وبنـ ً‬\n     ‫واإلجابــة وإقــرار املدعــى عليــه بكامــل مبلــغ الدعــوى ومقــداره عشــرون‬\n     ‫ألــف جنيــه بريطانــي واســتعداده بإرجاعــه للمدعــي باألصالــة يف شــهر‬\n     ‫ديســمبر ‪2013‬م ولقولــه يف الــروض املربــع ‪( 40/5‬بــل يثبــت بدلــه يف‬\n     ‫ذمتــه أي ذمــة املقتــرض حــا ًال ولــو أجلــه املقتــرض ألنــه عقــد منــع فيــه‬\n      ‫التفاضــل فمنــع األجــل فيــه كالصــرف قــال اإلمــام القــرض حــالٌ‬\n     ‫وينبغــي أن يفــي بوعــده انتهــى قــال يف احلاشــية ‪ 40/5‬ألن الوفــاء بالوعــد‬\n     ‫مســتحب ) انتهــى لذلــك كلــه فقــد ثبــت لــدي أن بذمــة املدعــى عليــه‬\n     ‫للمدعــي باألصالــة مبلغ ـ ًا مقــداره عشــرون ألــف جنيــه بريطانــي يلزمــه‬\n     ‫تســليمها إليــه حــا ًال وبذلــك حكمــت وقنــع املدعــي بالوكالــة باحلكــم‬\n     ‫وأمــا املدعــى عليــه فلــم يقتنــع وطلــب محكمــة االســتئناف مبوجــب‬\n     ‫الئحــة اعتراضيــة فأجيــب لطلبــه وأفهــم بــأن لــه مهلــة ثالثــن يومـ ًا لتقدمي‬\n     ‫الالئحــة االعتراضيــة اعتبــار ًا مــن ‪1434/6/14‬ه ـ وهــو موعــد اســتالم‬\n     ‫الصــك وإذا تأخــر اكتســب احلكــم القطعيــة ففهــم ذلــك وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/6/13‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد أعيــدت إلينــا املعاملــة مــن محكمــة‬\n\n\n‫‪91‬‬\n\f‫االســتئناف مبكــة املكرمــة وبرفقهــا القــرار الصــادر مــن الدائــرة‬\n‫احلقوقيــة الرابعــة برقــم ‪ 34340355‬وتاريــخ ‪1434/10/26‬ه ـ املرفــق‬\n‫باملعاملــة واملظهــر علــى الصــك املتضمــن املوافقــة علــى احلكــم ‪ .‬قاضــي‬\n‫اســتئناف ختمــه وتوقيعــه ‪ ،‬قاضــي اســتئناف ختمــه وتوقيعــه ‪ ،‬رئيــس‬\n‫الدائــرة ختمــه وتوقيعــه ‪ ،‬لــذا جــرى إحلاقــه وبــاهلل التوفيــق ‪ .‬حــرر يف‬\n                                                            ‫‪1434/12/23‬ه ـ‬\n‫احلمد هلل وحده‪ ،‬والصالة والســام على رســول اهلل ‪ ،‬وبعد‪ :‬فقد جرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ القاضــي باحملكمــة العامــة باملدينــة املنــورة املســجل بعــدد‬\n‫(‪ )34240537‬وتاريــخ ‪1434/6/13‬ه ـ املتضمــن دعــوى وكالــة ضــد‬\n‫(مصــري اجلنســية) واحملكــوم فيــه مبــا دون بباطنــه وبدراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪92‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":89,"source_page_end":92,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2db294adefa7b07d367f64f5d4403b9c53b8e05d21b07feedb3e1233b575ff84","normalized_text_hash":"91ac9d2c42a65c768ad8418e32d024139ce9bf097977934cc66b8347aba07085","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p89-34240537"},{"id":"c160f135-649d-5347-9c1e-bb0dd3f2d195","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -رد بينة لقرينة قوية -إنكار البينة -إفهام املدعي بأن له مين املدعى عليه مغلظة يف الصيغة -حكم برد دعوى -حكم بإخاء سبيل املدعى عليه .","document_number":"34185871","case_number":"296271102","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":"الدائرة احلقوقية السادسة رقم 34258691يف 1434/7/3ه ونص","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/13","year":"1434","subject":"قرض -رد بينة لقرينة قوية -إنكار البينة -إفهام املدعي بأن له مين املدعى عليه مغلظة يف الصيغة -حكم برد دعوى -حكم بإخاء سبيل املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/4/13 :‬هـ‬\n                      ‫ُ‬                 ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34185871 :‬‬\n                        ‫َر ْق ُم الدعوى‪296271102 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34258791‬تاريخه‪1434/7/3 :‬هـ‬\n\n\n\n     ‫قــرض‪ -‬رد بينــة لقرينــة قويــة ‪ -‬إنــكار البينــة ‪ -‬إفهــام املدعــي بــأن لــه‬\n     ‫ميــن املدعــى عليــه مغلظــة يف الصيغــة ‪ -‬حكــم بــرد دعــوى ‪ -‬حكــم‬\n                                            ‫بإخــاء ســبيل املدعــى عليــه ‪.‬‬\n\n\n\n\n     ‫‪ -1‬مــا أخرجــه البخــاري ومســلم مــن حديــث أبــى هريــرة رضــى اهلل عنــه‬\n     ‫قــال‪ :‬قــال‪ :‬رســول اهلل صلــى اهلل عليــه وســلم « بينمــا امرأتــان معهمــا‬\n     ‫ابناهمــا جــاء الذئــب فذهــب بابــن إحداهمــا فقالــت هــذه لصاحبتهــا‬\n     ‫إمنــا ذهــب بابنــك انــت وقالــت األخــرى إمنــا ذهــب بابنــك أنــت‬\n     ‫فتحاكمــا إلــى داود فقضــى بــه للكبــرى فخرجتــا إلــى ســليمان بــن‬\n     ‫داود عليهمــا الســام فأخبرتــاه فقــال ائتونــي بالســكني اشــقه بينكمــا‬\n     ‫فقالــت الصغــرى ال تفعــل يرحمــك اهلل هــو ابنهــا فقضى بــه للصغرى‪.‬‬\n     ‫قــال ابــن القيــم يف الطــرق احلكيمــة بعــد أن ســاق اخلبــر ( إن اإلقــرار إذا‬\n     ‫كان لعلــه اطلــع عليهــا احلاكــم لــم يلتفــت إليــه ولذلــك الغينا إقرار‬\n     ‫املريــض مــرض املــوت مبــال لوارثــه النعقــاد ســبب التهمــة واعتمــاد ًا على‬\n     ‫قرينــه احلــال يف قصــد تخصيصــه وممــن خــرج احلديــث الســابق اإلمــام‬\n     ‫النســائي وقــد ترجــم عليــه تراجــم عــدة منهــا قولــه «احلكــم بخــاف مــا‬\n     ‫يعتــرف بــه احملكــوم لــه إذا تبــن للحاكــم أن احلــق يف غيــر مــا اعتــرف‬\n                                                                                  ‫به»‬\n\n‫‪93‬‬\n\f‫قــال ابــن القيــم معلقــا علــى هــذه الترجمــة يف إعــام املوقعــن ‪371/4‬‬\n                                      ‫(هــذا هــو العلــم اســتنباطا ودليــا ) ‪.‬‬\n‫‪ -2‬قــال العــز بــن عبدالســام يف قواعــده ‪( 125/2‬القاعــدة يف األخبــار‬\n‫والدعــاوى والشــهادات واالقاريــر وغيرهــا أن مــا كذبــه العقــل أو جــوزه‬\n‫وإحالتــه العــادة فهــو مــردود ومــا أبعدتــه العــادة مــن غيــر إحالــة فلــه‬\n‫رتــب يف البعــد والقــرب قــد يختلــف فيهــا فمــا كان أبعــد وقوعــا فهــو‬\n‫أولــى بالــرد ومــا كان اقــرب وقوعــا فهــو أولــى بالقبــول وبينهمــا رتــب‬\n                                                                       ‫متفاوتــة‪.‬‬\n\n\n\n\n‫دعــوى املدعــى وكالــة ضــد املدعــى عليــه وكالــة ومضمــون الدعــوى‬\n‫أن املدعــي اصالــة ســلم للمدعــى عليــه اصالــة مبلغــا قــدره مليونــان‬\n‫وخمســمائة وثمانيــة عشــر ألفــا ومئتــان وتســعون ريــا ًال ســلفه ولــم يردهــا‬\n‫املدعــى عليــه وطالــب املدعــى وكالــة إلــزام املدعــى عليــه اصالــة بتســليم‬\n‫املبلــغ املدعــى بــه ملوكلــه ‪ ،‬أجــاب املدعــى عليــه وكالــة باإلنــكار ‪،‬‬\n‫ســأل ناظــر القضيــة املدعــى وكالــة عــن بينتــه فأبــرز كمبيالــة تتضمــن‬\n‫اقــرار ًا منســوبا للمدعــى عليــه اصالــة يتضمــن صحــة الدعــوى ‪ ،‬جــري‬\n‫عــرض الكمبيالــة علــى املدعــى عليــه وكالــة فانكرها وقــرر أنها غير‬\n‫صحيحــة ‪ ،‬وجــه ناظــر القضيــة ســؤاال للمدعــى وكالــة عــن كيفيــة‬\n‫اســتالم املدعــى عليــه اصالــة املبلــغ مــن موكلــه فأجــاب املدعــى وكالــة‬\n‫انــه اســتلم املبلــغ مــن موكلــه نقــد ًا ‪ ،‬قــرر ناظــر القضيــة بأنــه نظــرا إلــى‬\n‫أن املدعــى وكالــة ذكــر أن موكلــه ســلم للمدعــى عليــه املبلــغ نقــد ًا‬\n‫وهــذا أمــر تبعــده العــادة إذ يبعــد عــادة أن يســلم شــخص آلخــر مبلغــا‬\n\n                                                                                           ‫‪94‬‬\n\f     ‫كبيــر ًا جــدا عــد ًا ونقــد ًا وملــا جــاء يف حيثيــات القضيــة مــن نصــوص‬\n     ‫شــرعية فقــد صــدر احلكــم بــرد الدعــوى وإخــاء ســبيل املدعــى عليــه‬\n     ‫وافهــم ناظــر القضيــة املدعــى وكالــة بــأن ملوكلــه ميــن املدعــى عليــه‬\n     ‫مغلظــة يف الصيغــة متــى طلبهــا فأبــى طلبهــا وقــرر املدعــى عليــه وكالــة‬\n     ‫أن موكلــه مســتعد ببــذل اليمــن عنــد طلبهــا منــه ‪ ،‬صــدق احلكــم مــن‬\n                                                           ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة العامــة‬\n     ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة مبحافظــة جــدة املســاعد برقــم ‪296271102‬‬\n     ‫وتاريــخ ‪1431/11/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3198454‬وتاريــخ‬\n     ‫‪1431/11/25‬ه ـ وبعــد عــدة جلســات ويف يــوم الســبت املوافــق‪:‬‬\n     ‫‪1434/04/13‬ه ـ حضــر ‪ ....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n     ‫رقــم‪ :‬الوكيــل عــن ‪ ....‬بصفتــه وكيــا عــن‪ .... :‬مبوجــب الوكالــة‬\n     ‫الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب جــدة برقــم‪ 43329 :‬يف‪:‬‬\n     ‫‪1432/12/19‬ه ـ واملخــول لــه فيهــا حــق املرافعــة واملدافعــة وتعيــن‬\n     ‫اخلبــراء واإلنــكار وحضــر حلضــوره ‪ ....‬ســعودي اجلنســية مبوجــب الهويــة‬\n     ‫الوطنيــة رقــم ‪ ....‬الوكيــل عــن ‪ ....‬مبوجــب الوكالــة الصــادرة مــن‬\n     ‫كتابــة العــدل الثانيــة بشــمال جــدة رقــم ‪ 80049‬وتاريــخ ‪1429/8/11‬هـ‬\n     ‫ثــم ادعــى املدعــي وكالــة قائــا‪ :‬إن موكلــي قــد ســلم للمدعــى عليــه‪:‬‬\n     ‫فلســطيني اجلنســية مبوجــب رخصــة اإلقامــة رقــم‪ :‬مبلغــا قــدره‪ :‬اثنــان‬\n     ‫مليــون وخمــس مئــة وثمانيــة عشــر ألــف ومئتــان وتســعون ريــاال وهــي‬\n‫‪95‬‬\n\f‫عبــارة عــن ســلفة‪ ،‬ولــم يردهــا حتــى اآلن‪ ،‬أطلــب إلــزام املدعــى عليــه‬\n‫بتســليم املبلــغ املدعــى بــه وقــدره‪ :‬اثنــان مليــون وخمــس مئــة وثمانيــة‬\n‫عشــر ألــف ومئتــان وتســعون ريــاال‪ ،‬هكــذا ادعــى‪ .‬أجــاب املدعــى عليــه‬\n‫وكالــة بقولــه مــا ذكــره املدعــي وكالــة كلــه غير صحيــح‪ ،‬وأطلب رد‬\n‫دعــوى املدعــي وإخــاء ســبيل موكلــي منهــا‪ ،‬هكــذا أجــاب‪ .‬وبســؤاله‬\n‫عــن بينتــه أجــاب قائــا‪ :‬بينتــي هــذه الورقــة وجــرى اطالعنــا عليهــا وهــذا‬\n‫نصهــا‪( :‬كمبيالــة‪ ،‬اســتحقاق الدفــع ‪1430/2/1‬هـ مبلغهــا‪2518290 :‬‬\n‫ريــال املديــن‪ :‬إقامــة‪ . . . :‬أتعهــد أنــا املديــن املوقــع أعــاه بــأن أدفــع ألمــر‬\n‫الســيد املبلــغ املرقــوم أعــاه وقــدره‪ :‬اثنــان مليــون وخمــس مئــة وثمانيــة‬\n‫عشــر ألــف ومئتنــا وتســعون ريــاال بــدون تأخيــر وقــت الطلــب ‪ . . .‬حــررت‬\n‫يف‪2008/3/12 :‬م شــاهد توقيعــه املديــن (بــدون اســم) توقيعــه)‪ .‬ا‪ .‬ه ـ‬\n‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب قائــا‪ :‬مــا جــاء يف هــذه‬\n‫الكمبيالــة غيــر صحيحــة والتوقيــع الــذي عليهــا ليــس توقيــع موكلــي‪،‬‬\n‫هكــذا أجــاب‪ .‬وبســؤال املدعــي وكالــة عــن زيــادة بينــة أجــاب قائــا‪:‬‬\n‫ليــس لــدي ســوى مــا قدمــت‪ ،‬هكــذا أجــاب‪ .‬وبســؤاله كيــف ســلم‬\n‫موكلــه املبلــغ املدعــى بــه للمدعــى عليــه أصالــة أجــاب قائــا‪ :‬ســلمه‬\n‫نقــدا هكــذا أجــاب‪ .‬وبدراســة القضيــة وتأملهــا‪ ،‬ومبــا أن املدعــي‬\n‫وكالــة قــد ذكــر أن موكلــه أقــرض املدعــى عليــه مبلغــا قــدره‪ :‬اثنــان‬\n‫مليــون وخمــس مئــة وثمانيــة عشــر ألــف ومئتنــا وتســعون ريــال‪ ،‬ومبــا أن‬\n‫صحــة دعــواه جملــة وتفصي ـاً‪ ،‬ومبــا أن‬     ‫املدعــى عليــه قــد دفــع بعــدم ّ‬\n‫املدعــي وكالــة ذكــر أن موكلــه سـلّم املبلــغ املدعــى بــه للمدعــى عليــه‬\n‫عـ ّـد ًا ونقــداً‪ ،‬وهــذا أمــر ُتبعــده العــادة؛ إذ يبعــد عــادة أن ُيس ـلّم شــخص‬\n‫آلخــر مبلــغ كثيــر جــد ًا عـ ّـد ًا ونقـ ّـداً‪ ،‬ومــا أحالتــه العــادة أو أبعدتــه فهــو‬\n\n\n                                                                                               ‫‪96‬‬\n\f     ‫مــردود بقــول ابــن عبــد الســام يف قواعــده ‪( :125/2‬القاعدة يف األخبار‬\n     ‫والدعــاوى والشــهادات واألقاريــر وغيرهــا أن مــا كذبــه العقــل أو جــوزه‬\n     ‫وأحالتــه العــادة فهــو مــردود‪ ،‬وأمــا مــا أبعدتــه العــادة مــن غيــر إحالــة‬\n     ‫فلــه رتــب يف البعــد والقــرب قــد يختلــف فيهــا‪ ،‬فمــا كان أبعــد وقوع ـ ًا‬\n     ‫فهــو أولــى بالــرد ومــا كان أقــرب وقوع ـ ًا فهــو أولــى بالقبــول وبينهمــا‬\n     ‫رتــب متفاوتــة)‪ ،‬وألن اإلقــرار (الكمبيالــة) ـ علــى فــرض ثبوتــه ـ إذا‬\n     ‫شــهدت قرينــة قويــة بــر ّده لــم يعمــل به‪،‬برهــان ذلــك مــا أخرجــه البخــاري‬\n     ‫ومســلم مــن حديــث أبــي هريــرة رضــي اهلل عنــه قــال‪ :‬قــال رســول اهلل‬\n     ‫صلــى اهلل عليــه وســلم‪( :‬بينمــا امرأتــان معهمــا ابناهمــا جــاء الذئــب‬\n     ‫فذهــب بابــن أحدهمــا فقــال هــذه لصاحبتهــا إمنــا ذهــب بابنــك أنــت‬\n     ‫وقالــت األخــرى إمنــا ذهــب بابنــك أنــت فتحاكمــا إلــى داود فقضــى بــه‬\n     ‫للكبــرى فخرجتــا إلــى ســليمان بــن داود ـ عليهمــا الســام ـ فأخبرتــاه ‪،‬‬\n     ‫فقــال ائتونــي بالســكني أشــقه بينكمــا ‪ ،‬فقالــت الصغــرى ‪ :‬ال تفعــل‬\n     ‫يرحمــك اهلل هــو ابنهــا فقضــى بــه للصغــرى)‪ ،‬قــال ابــن القيــم يف الطــرق‬\n     ‫احلكميــة ص ‪ 6‬بعــد أن ســاق اخلبــر‪( :‬إن اإلقــرار إذا كان لعلــة اطلــع‬\n     ‫عليهــا احلاكــم لــم يلتفــت إليــه‪ ،‬ولذلــك ألغينــا إقــرار املريــض مــرض‬\n     ‫املــوت مبــال لوارثــه النعقــاد ســبب التهمــة واعتمــاد ًا علــى قرينــة احلــال يف‬\n     ‫قصــد تخصيصــه)‪ ،‬وممــن خـ ّـرج احلديــث الســابق اإلمــام النســائي وقــد‬\n     ‫ترجــم عليــه عــدة تراجــم منهــا قولــه ‪( :‬احلكــم بخــاف مــا يعتــرف بــه‬\n     ‫احملكــوم لــه إذا تبــن للحاكــم أن احلــق يف غيــر مــا اعتــرف بــه)‪ ،‬قــال‬\n     ‫ابــن القيــم معلقـ ًا علــى هــذه الترجمــة يف إعــام املوقعــن ‪( :371/4‬هــذا‬\n     ‫هــو العلــم اســتنباط ًا ودليـاً)‪ ،‬لذلــك ك ّلــه فقــد أعلمـ ُـت املدعــي وكالــة‬\n     ‫بــأن موكلــه ال يســتحق مــا ادعــاه جتــاه املدعــى عليــه مــن ثمــن القــرض‪،‬‬\n\n\n‫‪97‬‬\n\f‫ورددت دعــواه وأخليــت ســبيل املدعــى عليــه منهــا‪ ،‬وبذلــك قضيــت‪.‬‬\n‫وبإعــان احلكــم قــرر املدعــى عليــه وكالــة قناعتــه باحلكــم‪ ،‬وقــرر‬\n‫املدعــي وكالــة اعتراضــه فجــرى تســليمه نســخة مــن احلكــم وأفهــم‬\n‫بــأن لــه احلــق يف تقــدمي اعتراضــه ملــدة ثالثــن يومــا اعتبــارا مــن هــذا‬\n‫اليــوم وإذا انتهــت املــدة ولــم يقــدم اعتراضــه ســقط حقــه يف االعتــراض‬\n‫واكتســب احلكــم القطعيــة‪ .‬وأفهمــت املدعــي وكالــة بــأن ملوكلــه ميــن‬\n‫املدعــى عليــه املغلظــة بهــذه الصيغــة‪( :‬واهلل الــذي ال إلــه إال هــو عالــم‬\n‫الغيــب والشــهادة الرحمــن الرحيــم الطالــب الغالــب الضــار النافــع الــذي‬\n‫يعلــم خائنــة األعــن ومــا تخفــي الصــدور أننــي لــم اســتلم مــن املدعــي‬\n‫أصالــة‪ :‬مبلغــا قــدره‪ :‬اثنــان مليــون وخمــس مئــة وثمانيــة عشــر ألــف‬\n‫ومئتــان وتســعون ريــاال) متــى طلبهــا‪ ،‬فأبــى طلبهــا وليــس ل ــه إال ذلــك‬\n‫متــى طلبهــا‪ ،‬وقــد قــرر املدعــى عليــه وكالــة أن موكلــه مســتعد ببــذل‬\n‫اليمــن عنــد طلبهــا منــه‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                  ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/13‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/07/23‬ه ـ وقــد‬\n‫عــادت املعاملــة مــن محكمة االســتئناف مبكة املكرمــة وبرفقها قرار‬\n‫الدائــرة احلقوقيــة السادســة رقــم ‪ 34258691‬يف ‪1434/7/3‬ه ـ ونــص‬\n‫احلاجــة منــه‪( :‬وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم) ا‪.‬ه ـ وللبيــان جــرى إثباتــه وأمــرت بإحلاقــه‬\n‫بالصــك والســجل‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/23‬ه ـ‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد‪ :‬فق ــد ج ــرى‬\n‫م ّنــا نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n\n\n                                                                                     ‫‪98‬‬\n\f     ‫االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا احلكــم‬\n     ‫الصــادر مــن فضيلــة الشــيخ ‪ ....‬القاضــي باحملكمــة العامــة بجــدة‬\n     ‫واملســجل بع ــدد‪ 34185871‬وتاريــخ ‪1434/4/13‬هـ ـ املتضمــن دعــوى‬\n     ‫ضــد احملكــوم في ــه مبــا دون باطــن الصــك‪ ،‬وبدراس ــة احلكــم وص ــورة‬\n     ‫ضبط ــه و الئحتــه االعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم‪ ،‬واهلل‬\n        ‫املوفــق‪ .‬وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪99‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":93,"source_page_end":99,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6f2fb9fdc975b1bded0aeefef045a2802ffe1b59eecd5549ada2316a665254bb","normalized_text_hash":"1e45844fe27d9c4de530abe19141b27d63d49fb0c59bb4486a4d1bbc13ee14d5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p93-34185871"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"d0a8660b-0a64-5e88-936c-2f34422e614a","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -تخلف املدعى عليه عن احلضور رغم تبلغه -يعد احلكم حضوريا يف مواجهته -اليمن تشرع يف جانب أقوى املتداعين -من أدلة اإلثبات اإلقرار اخلطي و الشيك -إلزام املدعى عليه بسداد املبلغ املدعى به.","document_number":"33347755","case_number":"8020","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة االحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/20","year":"1434","subject":"قرض -تخلف املدعى عليه عن احلضور رغم تبلغه -يعد احلكم حضوريا يف مواجهته -اليمن تشرع يف جانب أقوى املتداعين -من أدلة اإلثبات اإلقرار اخلطي و الشيك -إلزام املدعى عليه بسداد املبلغ املدعى به.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/7/20 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33347755 :‬‬\n                            ‫َر ْق ُم الدعوى‪8020 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪/3416304‬ش‪ 2/‬تاريخه‪1434/1/19 :‬هـ‬\n\n\n\n     ‫قــرض ‪ -‬تخلــف املدعــى عليــه عــن احلضــور رغــم تبلغــه ‪ -‬يعــد احلكــم‬\n     ‫حضوريــا يف مواجهتــه‪ -‬اليمــن تشــرع يف جانــب أقــوى املتداعيــن ‪-‬مــن‬\n     ‫أدلــة اإلثبــات اإلقــرار اخلطــي و الشــيك ‪ -‬إلــزام املدعــى عليــه بســداد‬\n                                                              ‫املبلــغ املدعــى بــه‪.‬‬\n\n\n\n\n     ‫مــا قــرره الفقهــاء كشــيخ اإلســام ابــن تيميــة مــن أن اليمــن تشــرع يف‬\n                                                       ‫جانــب أقــوى املتداعيــن‪.‬‬\n\n\n\n\n     ‫حضــر املدعــي ولــم يحضــر املدعــى عليــه مــع تبلغــه ‪ ،‬قــرر القاضــي‬\n     ‫الســير يف نظــر الدعــوى وطلــب مــن املدعــي حتريــر دعــواه ‪ ،‬ادعــى‬\n     ‫املدعــي علــى املدعــى عليــه بأنــه أقرضــه مبلغـ ًا مــن املــال مبوجــب شــيك‬\n     ‫علــى أن يســدد القــرض خــال عــام وانتهــى األجــل ولــم يســدد القــرض‪،‬‬\n     ‫طلــب القاضــي مــن املدعــي البينــة علــى دعــواه ‪ ،‬أبــرز املدعــي صــورة‬\n     ‫الشــيك وإقــرار ًا خطيـ ًا منســوب ًا للمدعــى عليــه ‪ ،‬جــرى االطــاع عليهمــا‬\n     ‫ورصــد مضمونهمــا‪ ،‬جــرى مخاطبــه مؤسســه النقــد لإلفــادة عــن صرف‬\n     ‫املدعــى عليــه للشــيك‪ ،‬وردت اإلجابــة بصــرف املدعــى عليــه لشــيك آخــر‬\n\n\n‫‪63‬‬\n\f‫بنفــس التاريــخ واملبلــغ ‪ ،‬لتقــوي جانــب املدعــى بجــواب مؤسســه النقــد‬\n‫واإلقــرار اخلطــي املنســوب للمدعــى عليــه لــذا طلــب القاضــي مــن املدعــى‬\n‫اليمــن ‪ ،‬حلــف املدعــى اليمــن علــى صحــه دعــواه و أنــه لــم يتســلم مــن‬\n‫املدعــى عليــه شــيئ ًا ‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع املبلــغ‬\n‫املدعــى بــه للمدعــى وعــد احلكــم حضوري ـ ًا ‪ ،‬صــدق احلكــم مــن‬\n                                                      ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫العامــة‬\n    ‫ّ‬     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة‬\n‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة االحســاء برقــم ‪ 8020‬وتاريــخ ‪1431/11/29‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 3140479‬وتاريــخ ‪1431/11/29‬ه ـ حضــر‬\n‫‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬ولــم حتضــر املدعــى‬\n‫عليهــا وبتصفــح املعاملــة وجدنــا أن املدعــى عليــه ‪ ...‬قــد وقــع علــى ورقــة‬\n‫التبليــغ للجلســة املؤرخــة يف ‪1432/5/2‬ه ـ واملوقعــة مــن قبلــه وبســؤال‬\n‫املدعــي عــن دعــواه قــال إننــي أقرضــت املدعــى عليــه مبلغ ـ ًا وقــدره‬\n‫خمســون ألــف ريـ‪ 50000‬ــال يف ‪1430/10/20‬ه ـ مبوجــب الشــيك‬\n‫رقــم ‪ 000111‬يف ‪1430/10/20‬ه ـ علــى البنــك الســعودي األمريكــي‬\n‫علــى أن يســدد القــرض خــال عــام وحتــى تاريخــه لــم يســلمني مبلــغ‬\n‫القــرض وال جــزء منــه أطلــب إلزامــه بتســليمي مبلغ ـ ًا وقــدره خمســون‬\n‫ألــف ريـ‪ 50000‬ــال هــذه دعــواي فطلبــت مــن املدعــي البينــة فقــال البينــة‬\n‫هــي ورقــة إقــرار مكتوبــة بخــط يــده وأبــرز أصــل الورقــة فوجدتهــا‬\n‫طبــق مــا جــاء يف الدعــوى وعليــه فقــد قــررت الكتابــة ملؤسســة النقــد‬\n\n                                                                                     ‫‪64‬‬\n\f     ‫العربــي الســعودي لإلفــادة عــن رقــم الشــيك املذكــور وبيــان مصــدر‬\n     ‫الشــيك واملســتفيد منــه ويف جلســة أخــرى حضــر املدعــي ولــم يحضــر‬\n     ‫املدعــى عليــه وقــد وردنــا جــواب شــرطة ‪ ....‬برقــم ‪ 9/21‬ق ‪ 3103/‬يف‬\n     ‫‪1433/04/06‬ه ـ املتضمــن تعــذر تســليم املدعــى عليــه ‪ ...‬صــورة التبليــغ‬\n     ‫وباإلطــاع علــى البينــة التــي أبرزهــا املدعــي يف اجللســة املاضيــة لــم جنــد‬\n     ‫أنــه مت رصدهــا ونصهــا نعــم أنــا املدعــو ‪ ...‬ســعودي اجلنســية مبوجــب‬\n     ‫رقــم البطاقــة رقــم ‪ ...‬وتاريــخ ‪1404/07/08‬ه ـ الصــادرة مــن ‪ ....‬قــد‬\n     ‫اقترضــت مبلغ ـ ًا وقــدره خمســون ألــف ريــال ‪ 50000‬وذلــك عبــارة عــن‬\n     ‫قرضــة حســنة ويف ذمتــي للمدعــو ‪...‬الــذي اســتلمت منــه املبلــغ بشــيك‬\n     ‫رقــم ‪ 000111‬يف ‪1430/10/20‬ه ـ مــن البنــك األمريكــي وأن أســددها‬\n     ‫خــال عــام مــن تاريخــه واهلل علــى مــا أقــول شــهيد املقــر مبــا فيــه‬\n     ‫‪...‬توقيعــه انتهــى نصــه كمــا جــرى مخاطبــة مؤسســة النقــد العربــي‬\n     ‫الســعودي بخطابنــا رقــم ‪ 33561077‬يف ‪1433/03/23‬ه ـ لإلفــادة عــن‬\n     ‫الشــيك املذكــور يف ورقــة اإلقــرار املرصــودة بعاليــه فــورد اجلــواب برقــم‬\n     ‫‪22/3355‬س‪1779/‬يف ‪1433/05/18‬ه ـ ونصــه إشــارة خلطابكــم‬\n     ‫رقــم ‪ 33561077‬بتاريــخ ‪1433/03/27‬ه ـ بخصــوص اإلفــادة عــن‬\n     ‫الشــيك رقــم ‪ 000111‬بتاريــخ ‪1430/10/20‬ه ـ مببلــغ خمســن ألــف‬\n     ‫ريــال ‪ 50000‬الصــادر مــن حســاب املدعــي ‪ ...‬ســجل مدنــي رقــم ‪...‬لــدى‬\n     ‫مجموعــة ســامبا املاليــة ألمــر املدعــى عليــه ‪ ...‬ســجل مدنــي رقــم ‪...‬وهــل‬\n     ‫صــرف الشــيك أم ال وكيــف مت صرفــه ومــن املســتفيد مــن مبلغــه نــود‬\n     ‫اإلفــادة بأنــه ال يوجــد ســوى حســاب واحــد جــاري لــدى مجموعــة ســامبا‬\n     ‫املاليــة باســم املدعــي وقــد جــرى البحــث يف جميــع العمليــات املنفــذة‬\n     ‫علــى احلســاب منــذ تاريــخ فتحــه يف ‪2005/05/14‬م حتــى تاريخــه‬\n\n\n‫‪65‬‬\n\f‫ولــم تتوصــل املجموعــة للشــيك املشــار لــه علم ـ ًا بــأن مت التوصــل إلــى‬\n‫الشــيك رقــم ‪ 000112‬بــذات التاريــخ واملبلــغ واملســتفيد املدعــى عليــه‬\n‫حيــث مت صرفــه نقــد ًا للمدعــى عليــه بتاريــخ ‪2009/10/10‬م مرفــق‬\n‫نســخة الشــيك بعــد صرفــه ونعيــد لكــم خطابكــم ومرفقاتــه انتهــى‬\n‫نصــه وعليــه فقــد أفهمــت املدعــي بــأن مــا أبــرزه مــن إثبــات يعتبــر قرينــة‬\n‫يتقــوى بــه جانبــه وال بــد مــن ميينــه علــى أنــه أقــرض املدعــى عليــه املبلــغ‬\n‫املدعــى بــه وأنــه لــم يســتلم منــه شــيئ ًا وال يــزال يف ذمــة املدعــى عليــه حتــى‬\n‫اليــوم بعــد تذكيــره بخطــر اليمــن الكاذبــة فاســتعد بــأداء اليمــن‬\n‫ا واهلل العظيــم إننــي أقرضــت املدعــى عليــه ‪ ...‬مبلغـ ًا وقــدره‬      ‫فتلفــظ قائـ ً‬\n‫خمســون ألــف ريــال مبوجــب شــيك ولــم يقــم بتســليمي هــذا القــرض‬\n‫حتــى هــذا اليــوم وال يــزال يف ذمتــه واهلل علــى مــا أقــول شــهيد هكــذا‬\n‫حلــف فبنــاء علــى مــا تقــدم مــن الدعــوى وحيــث طالــب املدعــي املدعــى‬\n‫عليــه باملبلــغ املدعــى بــه وقــدره خمســون ألــف ريــال ولــم يحضــر املدعــي‬\n‫عليــه جلســات الدعــوى وأبــرز املدعــي بينتــه وهــي الورقــة التــي مت رصــد‬\n‫مضمونهــا وكذلــك إفــادة مؤسســة النقــد بــأن املدعــى عليــه املذكــور‬\n‫اســتلم الشــيك املرفــق صورتــه وصرفــه نقــدا وأن مصــدر الشــيك هــو‬\n‫املدعــي وحيــث تقــوي جانــب املدعــي وقــد قــرر بعــض الفقهــاء كشــيخ‬\n‫اإلســام ابــن تيميــة أن اليمــن تشــرع يف جانــب أقــوى املتداعيــن وحلــف‬\n‫املدعــي اليمــن املطلوبــة منــه لــذا فقــد حكمــت بإلــزام املدعــى عليــه ‪...‬‬\n‫بتســليم املدعــي مبلــغ وقــدره خمســون ألــف ريــال وأن احلكــم يف حــق‬\n‫املدعــى عليــه يعتبــر حكم ـ ًا حضوري ـ ًا لتبلغــه مبوعــد إحــدى اجللســات‬\n‫وســيتم تزويــده بنســخة مــن احلكــم لتقــدمي اعتراضــه عليــه خــال املــدة‬\n‫النظاميــة وهــي ثالثــون يومـ ًا مــن تاريــخ تســلمه وأنها إذا مضــت املدة دون‬\n\n\n                                                                                             ‫‪66‬‬\n\f     ‫تقــدمي اإلعتــراض فســوف يســقط حقــه يف طلــب اإلســتئناف ويكتســب‬\n     ‫احلكــم الصفــة القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/06/17‬ه ـ يف متــام الســاعة‬\n                                                          ‫الواحــدة وعشــر دقائــق ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد يف يــوم الســبت تاريــخ ‪1434/2/9‬ه ـ فقــد‬\n     ‫وردت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية برقــم‬\n     ‫‪332007805‬يف ‪1434/2/3‬ه ـ املقيــدة يف هــذه احملكمــة برقــم‬\n     ‫‪34/31669‬يف ‪1434/2/6‬ه ـ وبرفقهــا القــرار الصــادر مــن أصحــاب‬\n     ‫الفضيلــة قضــاة دائــرة األحــوال الشــخصية الثانيــة يف محكمــة‬\n     ‫االســتئناف باملنطقة الشــرقية رقم ‪/3416304‬ش‪2/‬يف ‪1434/1/19‬هـ‬\n     ‫نــص املقصــود منــه بدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n     ‫قررنــا املصادقــة علــى حكــم فضيلتــه واهلل املوفــق قضــاة محكمــة‬\n     ‫االســتئناف وهــم ‪ ...‬و‪...‬ورئيــس الدائــرة د‪...‬وعليــه توقيــع وختــم لــكل‬\n     ‫واحــد منهــم وللبيــان حــرر يف ‪1434/2/9‬ه ـ وصلــى اهلل علــى نبينــا‬\n                                            ‫محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪67‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":63,"source_page_end":67,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5ca676d939ef2e218962078946e8282841ad9361db08795b89d48ee700fa4980","normalized_text_hash":"037880a84ddf361f6267bb373df16ba33f2f9011171ad446eca306b785adcf76","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p63-33347755"},{"id":"6bb9986b-923d-5155-b096-1bfb4dcd828a","document_type":"judgment","category":"judicial","subcategory":"general","title":"إقراض -ادعاء مضاربة -بينة املدعي غير موصلة -شهود املدعى عليه بنفي ادعاء املدعي -تعديل الشهود -رد دعوى -إخاء سبيل.","document_number":"3418117","case_number":"33367047","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة االحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"إقراض -ادعاء مضاربة -بينة املدعي غير موصلة -شهود املدعى عليه بنفي ادعاء املدعي -تعديل الشهود -رد دعوى -إخاء سبيل.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/20 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3418117 :‬‬\n                   ‫َر ْق ُم الدعوى‪33367047 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34178176‬تاريخه‪1434/4/3 :‬هـ‬\n\n\n\n‫إقــراض ‪ -‬ادعــاء مضاربــة ‪ -‬بينــة املدعــي غيــر موصلــة ‪ -‬شــهود املدعــى‬\n‫عليــه بنفــي ادعــاء املدعــي ‪ -‬تعديــل الشــهود ‪ -‬رد دعــوى ‪ -‬إخــاء ســبيل‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                    ‫حكمه ‪.‬‬\n\n\n\n\n‫ادعــى املدعــى علــى املدعــى عليــه أنــه أعطــاه مائــة وخمســة وخمســن‬\n‫ألــف ريــال ليضــارب بهــا ولــم يرجــع إليــه شــيء منهــا وقــد رد املدعــى‬\n‫عليــه هــذه الدعــوى وقــال أن هــذه األمــوال كانــت قرض ـ ًا حســن ًا منــي‬\n‫إليــه وهــو ردهــا إلــي وأحضــر الشــهود علــى ذلــك وعليــه قــرر القاضــي‬\n‫عــدم ثبــوت الدعــوى وإخــاء ســبيل املدعــى عليــه وقــد اعتــرض املدعــي‬\n              ‫علــى احلكــم وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                 ‫‪68‬‬\n\f     ‫العامــة‬\n        ‫ّ‬     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة‬\n     ‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة مبحافظــة االحســاء برقــم ‪ 33367047‬وتاريــخ ‪1433/05/29‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 331008742‬وتاريــخ ‪ 1433/05/29‬ه ـ ففــي‬\n     ‫يــوم الســبت املوافــق‪ 1433/07/19‬ه ـ وفيهــا حضــر املدعــي أصالــة‬\n     ‫‪...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪ ...‬وادعــى علــى احلاضــر معــه‬\n     ‫‪...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪...‬قائــا املدعــي يف حتريــر‬\n     ‫دعــواه إن هــذا احلاضــر معــي قــد اســتلم منــي مبلــغ خمســة وخمســن‬\n     ‫ألــف ريـ‪ 55000‬ــال مبوجــب الشــيك الصــادر مــن البنــك ‪...‬برقــم ‪...‬يف‬\n     ‫‪2001/3/3‬م واســتلم أيضــا مبلــغ مائــة ألــف ريـ‪ 100000‬ــال مبوجــب‬\n     ‫الشــيك الصــادر مــن البنــك ‪...‬برقــم ‪...‬يف ‪1421/11/15‬ه ـ فــكان‬\n     ‫املجمــوع مائــة وخمســة وخمســن ألــف ريـ‪ 155000‬ــال علــى أن أضــارب‬\n     ‫لــه يف األســهم بنســبة ‪ %25‬و‪ %75‬للمدعــى عليــه ولــم يــرد املدعــى عليــه‬\n     ‫املبلــغ وال األربــاح أطلــب إلــزام املدعــى عليــه بإرجــاع املبلــغ املذكــور هذه‬\n     ‫دعواي وبعرض ذلك على املدعى عليه أجاب بقوله إن ماذكره املدعي‬\n     ‫غيــر صحيــح جملــة وتفصيــا والصحيــح أنــي اســتلمت هــذا املبلغ ســدادا‬\n     ‫للمبلــغ الــذي كان يف ذمتــه لــي حيــث أنــه اقتــرض منــي هــذا املبلــغ ومت‬\n     ‫ســداده مبوجــب هــذه الشــيكات هكــذا أجــاب وبســؤالهما عــن بينتهما‬\n     ‫أحضــر املدعــى عليــه شــاهدا يدعــى ‪...‬ســعودي مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪...‬مــن مواليــد ‪1395/5/27‬ه ـ وبســؤال الشــاهد عــن وجــود صلــة‬\n     ‫قرابــه بينــه وبــن املدعــن فأجــاب بقولــه ليــس بينــي وبينهمــا صلــة قرابــه‬\n\n‫‪69‬‬\n\f‫ســوى الصداقــة وبســؤاله عمــا لديــه مــن شــهادة أجــاب بقولــه أشــهد هلل‬\n‫تعالــى بأنــه منــذ أكثــر مــن عشــر ســنوات تقريبــا طلــب منــي ‪...‬مبلغــا مــن‬\n‫املــال فأحضــرت لــه املدعــى عليــه وقــام املدعــى عليــه بإقــراض املدعــي‬\n‫مبلغــا مقــداره مائــه وخمســه وخمســون ألــف ريــال وقــد أخبرنــي املدعــى‬\n‫عليــه بأنــه اســتلم املبلــغ مــن املدعــي مبوجــب شــيكات هــذا مــا لــدي وبــه‬\n‫أشــهد هلل تعالــى وبعــرض الشــاهد وشــهادته علــى املدعــي أجــاب بقولــه‬\n‫إن شــهادة الشــاهد غيــر صحيحــه وأنــا ال أطعــن يف دينــه وأمانتــه هكــذا‬\n‫أجــاب ثــم أحضــر املدعــى عليــه شــاهدا آخــر يدعــى ‪ ...‬ســعودي مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬وهــو مــن مواليــد ‪1390/2/4‬ه ـ وبســؤال الشــاهد‬\n‫عــن وجــود صلــة قرابــه بينــه وبــن املدعــن فأجــاب بقولــه ليــس بينــي‬\n‫وبينهمــا صلــة قرابــه ســوى الصداقــة بينــي وبــن املدعــى عليــه وبســؤاله‬\n‫عمــا لديــه مــن شــهادة أجــاب بقولــه أشــهد هلل تعالــى أنــه منــذ أكثــر‬\n‫مــن عشــر ســنوات أقــرض املدعــى عليــه ‪ ...‬مبلغــا مقــداره مائــه وخمســه‬\n‫وخمســون ألــف ريــال قــرض حســن وقــد كنــت حاضــرا معهمــا وقــد‬\n‫كتــب بهــا ورقــة ثــم أبلغنــا بعــد فتــرة عــواد أنــه اســتلم املبلــغ مــن املدعــي‬\n‫هــذا مــا حصــل وبــه أشــهد هلل تعالــى وبعــرض الشــاهد وشــهادته علــى‬\n‫املدعــي أجــاب بقولــه بــأن شــهادته غيــر صحيحــه وأنــا ال أطعــن يف دينــه‬\n‫وأمانتــه هــذا وقــد جــرى تعديــل الشــاهدين مــن قبــل ‪...‬ســعودي مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬و‪...‬ســعودي مبوجــب الســجل املدنــي رقم ‪...‬وشــهدا‬\n‫بقولهمــا نشــهد هلل تعالــى بعدالــة الشــاهدين املذكوريــن وأنهــا عــدالن‬\n‫وثقــة وإن شــهدا علينــا هكــذا أجابــا فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وحيــث أنكــر املدعــى عليــه دعــوى املدعي وادعى أن اســتالمه‬\n‫هــذا املبلــغ لكونــه قــرض أقرضــه املدعــي وأحضــر البينــة علــى صحــة‬\n\n\n                                                                                            ‫‪70‬‬\n\f     ‫مــا ذكــر املدعــى عليــه وحيــث أنــه ال يحــل مــال امــرىء مســلم إال بطيــب‬\n     ‫نفــس منــه لــذا وجلميــع مــا تقــدم لــم تثبــت لــدي دعــوى املدعــي قبــل‬\n     ‫املدعــى عليــه وثبــت لــدي أن اســتالمه لهــذا املبلــغ كان مقابــل قــرض‬\n     ‫اســتلمه املدعــى عليــه مــن املدعــي وأخليــت ســبيل املدعــى عليــه وبذلــك‬\n     ‫حكمــت وبعرضــه عليهمــا قــرر املدعــي عــدم قناعتــه وطلــب االســتئناف‬\n     ‫فأفهــم باملراجعــة يــوم الســبت ‪1434/1/24‬ه ـ الســتالم صــورة مــن صــك‬\n     ‫احلكــم ليتمكــن مــن تقــدمي الئحــة اعتــراض عليــه ففهــم ذلــك وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n     ‫حــرر يف ‪1434/01/20‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى‬\n     ‫رســولنا محمــد و آلــه وصحبــه أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة‬\n     ‫الدائ ــرة احلقوقيــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية‬\n     ‫علــى املعاملــة الــواردة مــن فضيلــة القائــم بعمــل رئيــس احملكمــة العامــة‬\n     ‫مبحافظة األحســاء برقم ‪ 331008742‬وتاريخ ‪1434/2/19‬هـ واملقيدة‬\n     ‫لــدى احملكمــة برقــم ‪ 34455056‬وتاريــخ ‪1434/2/24‬ه ـ املرفــق بهــا‬\n     ‫الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ... /‬املسـ ّـجل‬\n     ‫برقــم ‪...‬وتاريــخ ‪1434/1/20‬ه ـ اخلــاص بدعــوى‪... /‬ضــد‪... /‬يف قضيــة‬\n     ‫حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n     ‫فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n     ‫املعاملــة قررنــا املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى ضــرورة‬\n     ‫تعديــل لفــظ املدعــي يف الضبــط إلــى لفــظ املدعــى عليــه يف املوضعــن‬\n     ‫املشــار إليهمــا بقلــم الرصــاص يف الصــك عنــد إحضــار الشــاهدين‬\n     ‫وذلــك قبــل بعــث املعاملــة إلــى اجلهــة اإلداريــة املختصــة‪ ،‬ولبيانــه حــرر يف‬\n                                             ‫‪1434/4/2‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n‫‪71‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":68,"source_page_end":71,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"50d61d7f111b1563618e2fcde44553b32a169aea3ef7e03a282006f280dae7bf","normalized_text_hash":"f6a897b0a1008532100e6c57e6fa1d7d528d1ee3a5ca3f18aa129acff2c8c3fd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p68-3418117"},{"id":"e19044ad-5ab8-596d-b3f0-e7225c0409dd","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -ضمان -مطالبة الضامن للمضمون بسداد ما سلمه عنه للمضمون له -محرر عريف وشهادة شهود سند ا للدعوى -طلب اليمن من جانب أقوى املتداعين -اعتبار عدم حضور املدعى عليه املتبلغ باجللسة نكو ال عن اجلواب وقرينه تضعف جانبه وتقوى جانب املدعي -احلكم حضوري يف حالة النكول -رفع احلكم احلضوري إلى محكمة اإلستئناف دون الئحة .","document_number":"34293933","case_number":"33581048","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/10","year":"1434","subject":"قرض -ضمان -مطالبة الضامن للمضمون بسداد ما سلمه عنه للمضمون له -محرر عريف وشهادة شهود سند ا للدعوى -طلب اليمن من جانب أقوى املتداعين -اعتبار عدم حضور املدعى عليه املتبلغ باجللسة نكو ال عن اجلواب وقرينه تضعف جانبه وتقوى جانب املدعي -احلكم حضوري يف حالة النكول -رفع احلكم احلضوري إلى محكمة اإلستئناف دون الئحة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/10 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34293933 :‬‬\n                   ‫َر ْق ُم الدعوى‪33581048 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34356175‬تاريخه‪1434/11/10 :‬هـ‬\n\n\n\n‫قــرض ‪ -‬ضمــان ‪ -‬مطالبــة الضامــن للمضمــون بســداد مــا ســلمه عنــه‬\n‫للمضمــون لــه ‪ -‬محــرر عــريف وشــهادة شــهود ســند ًا للدعــوى ‪ -‬طلــب‬\n‫اليمــن مــن جانــب أقــوى املتداعيــن ‪ -‬اعتبــار عــدم حضــور املدعــى عليه‬\n‫املتبلــغ باجللســة نكــو ًال عــن اجلــواب وقرينــه تضعــف جانبــه وتقــوى‬\n‫جانــب املدعــي ‪ -‬احلكــم حضــوري يف حالــة النكــول ‪ -‬رفــع احلكــم‬\n                       ‫احلضــوري إلــى محكمــة اإلســتئناف دون الئحــة ‪.‬‬\n\n\n\n\n‫املــادة اخلامســة واخلمســون مــن نظــام املرافعــات الشــرعية ولوائحهــا‬\n                                                            ‫التنفيذية ‪.‬‬\n\n\n\n\n‫دعــوى املدعــى ضــد املدعــى عليهــا الغائبــة عــن مجلــس احلكــم التــي‬\n‫تبلغــت مبوعــد اجللســة وحــرر املدعــى دعــواه مضمونهــا أن املدعــى عليهــا‬\n‫اقترضــت مــن شــخص مبلغــا قــدره مئتــا ألــف ريــال وان املدعــى ضمنهــا‬\n‫يف املبلــغ لــدى املقتــرض وأن املدعــى عليهــا لــم تســدد املبلــغ وان املقــرض‬\n‫طالــب املدعــى بالســداد وســلم املدعــى املقــرض كامــل مبلــغ القــرض‬\n‫الــذي يف ذمــة املدعــى عليهــا ‪ ،‬أحضــر املدعــى بينــة موصلــه علــى صحــة‬\n\n                                                                                     ‫‪72‬‬\n\f     ‫الدعــوى عبــارة ســندين وشــاهدين مت تعديلهمــا التعديــل الشــرعي ‪ ،‬قــرر‬\n     ‫ناظــر القضيــة طلــب اليمــن مــن املدعى على صحة دعــواه وحلف املدعى‬\n     ‫علــى صحــة الدعــوى ‪ ،‬قــرر ناظــر القضيــة انــه بنــاء علــى الدعــوى والبينة‬\n     ‫املوصلــة واليمــن مــن املدعــى وألن امتنــاع املدعــى عليهــا مــن حضــور‬\n     ‫جلســات القضيــة يضعــف جانبهــا ويقــوى جانــب املدعــي وملشــروعية‬\n     ‫اليمــن يف جانــب أقــوى املتداعــن وملــا جــاء يف أســباب احلكــم فقــد‬\n     ‫صــدر احلكــم علــى املدعــى عليهــا بــأن تســلم للمدعــى املبلــغ املدعــى‬\n     ‫بــه ‪ ،‬قــرر ناظــر القضيــة أن احلكــم يف حــق املدعــى عليهــا حضــوري‬\n     ‫وبعــث نســخة مــن الصــك للمدعــى عليهــا حســب التعليمــات ‪ ،‬مت تســليم‬\n     ‫صــورة الصــك للمدعــى عليهــا ورفضــت التوقيــع ‪ ،‬صــدر قــرار محكمــة‬\n                       ‫االســتئناف مبكــة املكرمــة باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n     ‫‪ .......‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة‬\n     ‫احملالــة لنــا مــن فضيلــة رئيس احملكمة العامة مبحافظة جدة‪/‬املســاعد‬\n     ‫برقــم ‪ 33581048‬وتاريــخ ‪1433/09/19‬ه ـ املقيــدة باحملكمــة برقــم‬\n     ‫‪ 331727907‬وتاريخ ‪1433/09/19‬هـ حضر ســعودي اجلنســية مبوجب‬\n     ‫الســجل املدنــي رقــم ولــم حتضــر املدعــى عليهــا وال مــن ينــوب عنها وقد‬\n     ‫تبلغــت باملوعــد فادعــى قائــا يف دعــواه لقــد اقترضــت املدعــى عليهــا‬\n     ‫مــن املدعــو ‪ .....‬مبلغــا وقــدره مائتــا ألــف ريــال وقــد ضمنتهــا يف املبلــغ‬\n     ‫ولــم تســدد املدعــي عليهــا املبلــغ وال شــيئا منــه للمدعــو ‪ .....‬فطالبنــي‬\n\n‫‪73‬‬\n\f‫باملبلــغ فدفعتــه لــه كامــا اطلــب إلــزام املدعــى عليهــا بــأن تدفــع لــي‬\n‫مبلغــا وقــدره مائتــا ألــف ريــال هــذه دعــواي فجــرى ســؤاله هــل لديــه بينــة‬\n‫تثبــت صحــة دعــواه فقــال نعــم ومســتعد بإحضارهــا يف اجللســة القادمــة‬\n‫ويف جلســة أخــرى حضــر املدعــي ولــم حتضــر املدعــى عليهــا وال مــن‬\n‫ينــوب عنهــا وقــد تبلغــت باملوعــد وبســؤال املدعــي عــن البينــة التــي وعــد‬\n‫بإحضارهــا أبــرز ســندا وباالطــاع عليــه وجــد فيــه مــا نصــه ( أقــر أنــا‬\n‫‪ /‬ســعودية اجلنســية قــد إقترضــت مبلــغ وقــدره مائتــان ألــف ريــال نقــدا‬\n‫مــن الســيد ‪ /‬ســعودي اجلنســية قرضــة حســنة تــرد حــن الطلــب وســوف‬\n‫أقــوم بســداد املبلــغ املذكــور وقــدره مائتــان ألــف ريــال ســعودي بتاريــخ‬\n‫‪1429/09/03‬ه ـ وذلــك ألجــل الذهــب توقيــع الشــاهد توقيــع كفيــل‬\n‫غــرم وأداء توقيــع شــاهد توقيــع الشــاهد توقيــع ) وبســؤاله هــل لديــه‬\n‫زيــادة بينــة قــال نعــم لــدي شــهود الســند ومســتعد بإحضارهــم يف اجللســة‬\n‫القادمــة ويف جلســة أخــرى حضــر املدعــي ولــم حتضــر املدعــى عليهــا‬\n‫وال مــن ينــوب عنهــا وقــد تبلغــت باملوعــد مبوجــب محضــر التبليــغ رقــم‬\n‫‪( 34681257‬بــدون تاريــخ) كمــا تبلغــت املدعــى عليهــا مبوعــد اجللســة‬\n‫املنعقــدة بتاريــخ ‪1434/05/12‬ه ـ مبوجــب محضــر التبليــغ (بــدون رقــم‬\n‫وال تاريــخ) املرفــق يف املعاملــة كمــا تبلغــت مبوعــد اجللســة املنعقــدة‬\n‫بتاريــخ ‪1434/07/11‬ه ـ مبوجــب محضــر التبليــغ رقــم ‪ 341508010‬يف‬\n‫‪1434/06/21‬ه ـ املرفــق يف املعاملــة وبســؤال املدعــي عــن البينــة التــي‬\n‫وعــد بإحضارهــا أبــرز ســندا وباالطــاع عليــه وجــد فيــه مــا نصــه ( بســم‬\n‫اهلل الرحمــن الرحيــم إقــرار باســتالم مبلــغ (‪ )200.000‬مئتــا ألــف ريــال‬\n‫بهــذا أقــر‪ .....‬أنــا ســجل مدنــي رقــم ( ) بأننــي قــد اســتلمت مــن املكــرم ‪/‬‬\n‫ســجل مدنــي رقــم ( ) ككفيــل غــارم للســيدة ‪ ......‬ســجل مدنــي رقــم ( )‬\n\n\n                                                                                       ‫‪74‬‬\n\f     ‫مبلــغ وقــدره (‪ )200.000‬مئتــا ألــف ريــال ســعودي بعــد أن التــزم بالســداد‬\n     ‫عنهــا يف حــال فشــلها يف الســداد مبوجــب الســند املوقــع وممهــور ببصمــة‬\n     ‫املذكــورة أعــاه وذلــك بعــد أن فشــلت يف ســداد املبلــغ املوضــح بالســند‬\n     ‫املذكــور ‪1429/09/03‬ه ـ رغــم مطالبتــي لهــا طــوال الفتــرة الســابقة‬\n     ‫بالســداد وهــي تقــوم بالتهــرب وإعطائــي الوعــود الكاذبــة فهــذا ممــا‬\n     ‫اطرنــي ملطالبــة كفيلهــا‪ ......‬وقــام بدفــع كامــل املبلــغ عنهــا‪ .‬وبتوقيعــي‬\n     ‫علــى هــذا اإلقــرار ابــرأ ذمــة املكــرم ‪ ......‬مــن أي مطالبــة ماليــة‬\n     ‫بخصــوص هــذا املبلــغ ألي طــرف آخــر‪ ،‬وهــذا اإلقــرار يعتبــر مخالصــة‬\n     ‫نهائيــة ال رجعــة عنهــا يف مواجهتــه ‪ ،‬وبذلــك يحــق لــه املذكــور بعاليــه‬\n     ‫ا ‪ .‬وأذنــت ملــن يشــهد واهلل علــي‬  ‫الرجــوع عليهــا ملطالبتهــا باملبلــغ كامـ ً‬\n     ‫مــا أقــول شــهيد ‪1433/09/02 ...‬ه ـ شــهد بذلــك ســجل مدنــي رقــم ‪......‬‬\n     ‫توقيــع و ســجل مدنــي رقــم ‪ ......‬توقيــع و ســجل مدنــي رقــم ‪ ......‬توقيــع و‬\n     ‫ســجل مدنــي رقــم ‪ ......‬توقيــع) ثــم أحضــر املدعــي للشــهادة مينــي اجلنســية‬\n                                 ‫مبوجــب اإلقامــة رقــم ‪ ......‬وقــرر الشــاهد قائــا ‪.‬‬\n     ‫أشــهد هلل تعالــى أن املدعــى عليهــا قــد اســتلمت مــن املدعــو مبلغــا وقــدره‬\n     ‫مائتــا ألــف ريــال كقــرض حســن وضمنهــا املدعــي يف الثمــن ومت توقيــع‬\n     ‫ســند بحضــوري وهــو الــذي أبــرزه املدعــي يف جلســة ســابقة كمــا قــام‬\n     ‫املدعــي بســداد املبلــغ وقــدره مائتــا ألــف ريــال للمدعــو ومت توقيــع ســند‬\n     ‫بحضــوري وهــو املرصــود نصــه أعــاه هكــذا شــهد كمــا أحضــر‬\n     ‫املدعــي للشــهادة ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وقــرر‬\n     ‫الشــاهد ‪ .....‬قائــا أشــهد هلل تعالــى أن املدعيــة قــد اســتلمت مــن املدعــو‬\n     ‫‪ .....‬مبلغــا وقــدره مائتــا ألــف ريــال كقــرض حســن وضمنهــا املدعــي يف‬\n     ‫الثمــن ومت توقيــع ســند بحضــوري وهــو الــذي أبــرزه املدعــي يف جلســة‬\n\n\n‫‪75‬‬\n\f‫ســابقة كمــا قــام املدعــي بســداد املبلــغ وقــدره مائتــا ألــف ريــال للمدعــو‬\n‫‪ .....‬ومت توقيــع ســند بحضــوري وهــو املرصــود نصــه أعــاه هكــذا شــهد‬\n‫فجــرى ســؤال املدعــي هــل لديــه زيــادة بينــة فقــال أكتفــي مبــا قدمتــه‬\n‫هكــذا قــرر فطلبــت منــه إحضــار معدلــن لشــاهديه فاســتعد ويف‬\n‫جلســة أخــرى حضــر املدعــي ولــم حتضــر املدعــى عليهــا وال مــن ينــوب‬\n‫عنهــا وبســؤال املدعــي عمــا اســتمهل ألجلــه أحضر ‪ .....‬ســعودي بالســجل‬\n‫املدنــي رقــم ‪ ......‬وقــرر علــي قائــا أشــهد هلل تعالــى أن الشــاهدين عدالن‬\n‫ثقتــان هكــذا شــهد كمــا أحضــر ســعودي بالســجل املدنــي رقــم وقــرر‬\n‫قائــا أشــهد هلل تعالــى أن الشــاهدين عــدالن ثقتــان هكــذا شــهد ثــم‬\n‫عرضــت علــى املدعــي أن يحلــف اليمــن التــي هــذا نصهــا واهلل الــذي ال‬\n‫إلــه إال هــو وال رب ســواه لقــد اقترضــت املدعــى عليهــا مــن املدعــو‪......‬‬\n‫مبلغــا وقــدره مائتــا ألــف ريــال وقــد ضمنتهــا يف املبلــغ وقمــت بتســديد‬\n‫املبلــغ كامــا للمدعــو بعــد أن طالبنــي بــه ولــم تســدد لــي املدعــى عليهــا‬\n‫هــذا املبلــغ وال شــيئا منــه واهلل العظيــم وجــرى وعظــه وتخويفــه مــن‬\n‫عاقبــة اليمــن الكاذبــة فاســتعد ببذلهــا ثــم حلــف قائــا واهلل الــذي ال‬\n‫إلــه إال هــو وال رب ســواه لقــد اقترضــت املدعــى عليهــا ‪ ......‬مــن املدعــو‬\n‫‪ .....‬مبلغــا وقــدره مائتــا ألــف ريــال وقــد ضمنتهــا يف املبلــغ وقمــت بتســديد‬\n‫املبلــغ كامــا للمدعــو ‪ .....‬بعــد أن طالبنــي بــه ولــم تســدد لــي املدعــى‬\n‫عليهــا هــذا املبلــغ وال شــيئا منــه واهلل العظيــم هكــذا حلــف فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى وشــهادة الشــاهدين املعدلــن شــرعا ومــا تضمنتــه‬\n‫الســندات التــي أبرزهــا املدعــي واليمــن التــي بذلهــا وألن امتنــاع املدعــى‬\n‫عليهــا عــن حضــور ثــاث جلســات رغــم تبلغهــا بهــا وعــدم تقدميهــا عــذرا‬\n‫عــن عــدم احلضــور رغــم تباعــد مواعيد هذه اجللســات يعد نكوال وقرينة‬\n\n\n                                                                                        ‫‪76‬‬\n\f     ‫تضعــف جانبهــا وتقــوي جانــب املدعــي وألن اليمــن تشــرع يف جنبــة أقــوى‬\n     ‫املتداعيــن وجانــب املدعــي واحلــال مــا ذكــر أقــوى واســتنادا للمــادة‬\n     ‫اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية ولوائحهــا التنفيذيــة‬\n     ‫لذلــك كلــه فقــد حكمــت علــى املدعى عليها ســعودية اجلنســية مبوجب‬\n     ‫الســجل املدنــي رقــم بــأن تدفــع للمدعــي مبلغــا وقــدره مائتــا ألــف ريــال‬\n     ‫ويعــد حكمــي هــذا يف حــق املدعــى عليهــا حضوريــا وقــررت بعــث‬\n     ‫نســخة مــن احلكــم للمدعــى عليهــا عــن طريــق اجلهــة املختصــة لتســليمها‬\n     ‫وذلــك لتقــدمي الالئحــة اإلعتراضيــة خــال ثالثــن يومـ ًا مــن إســتالمها لــه‬\n     ‫إن أرادت وتفهــم بأنــه إن مضــت املــدة احملــددة لإلعتــراض ولــم تتقــدم‬\n     ‫بالالئحــة اإلعتراضيــة فــإن حقهــا يســقط يف طلــب االســتئناف ويصبــح‬\n     ‫احلكــم مكتســب ًا القطعيــة ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/08/10‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف‬\n     ‫يــوم األحــد املوافــق ‪ 1434/10/25‬ه ـ افتتحــت اجللســة بعــد أن وردنــا‬\n     ‫خطــاب مديــر شــرطة الشــمالية مبحافظــة جــدة برقــم ‪ 6/12532‬يف‬\n     ‫‪1434/09/17‬ه ـ املتضمــن(مت تســليم صــورة صــك احلكــم عــن طريــق‬\n     ‫منــدوب العمــدة ورفضــت التوقيــع) بنــاء علــى ذلــك ومبــا أن املــادة ‪5/176‬‬\n     ‫مــن الالئحــة التنفيذيــة لنظــام املرافعــات الشــرعية تنــص علــى أنــه إذا‬\n     ‫تعــذر تســليم نســخة احلكــم الغيابــي للمحكــوم عليــه أو وكيلــه فإنــه‬\n     ‫يرفــع حملكمــة التمييــز بــدون الئحــة إعتراضيــه لــذا فقــد قــررت إرســال‬\n     ‫املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم حســب التعليمــات ‪،‬‬\n     ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪1434/10/25‬ه ـ‬\n\n\n‫‪77‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد ففــي‬\n‫يــوم الثالثــاء املوافــق ‪ 1434/12/17‬ه ـ افتتحــت اجللســة وقــد عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪ 34356175‬يف‬\n‫‪1434/11/10‬ه ـ ونــص احلاجــة منــه (وبدراســة احلكــم وصــورة ضبطــه‬\n‫تقــررت املوافقــة علــى احلكــم ‪ ،‬قاضــي اســتئناف ختــم وتوقيــع قاضــي‬\n‫اســتئناف ختــم وتوقيــع رئيــس الدائــرة ختــم وتوقيــع )عليــه فقــد أمــرت‬\n‫بإثباتــه علــى ضبطــه وســجله حتــى ال يخفــى ‪ ،‬وبــاهلل التوفيــق وصلى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/12/17‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبحافظــة جــدة برقــم ‪331727907‬‬\n‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ القاضــي باحملكمــة‬\n‫العامــة بجــدة واملســجل بعــدد ‪ 34293933‬وتاريــخ ‪1434/8/10‬هـ ـ‬\n‫واملتضمــن دعــوى‪ ......‬ضــد‪ ......‬واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم واهلل‬\n      ‫املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                   ‫‪78‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":72,"source_page_end":78,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"86e3ce97c70437f3b8eeeadf2823e361d93bc9160ee23e23414718ca23c32160","normalized_text_hash":"0cdcec9056c7fea683759b78a9546e6db2ff5372042c028f5d2c1690b09f04bf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p72-34293933"},{"id":"4cb0c047-a938-5112-b700-4e50ec67dd3d","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -عقد بيع -مطالبة بدين مورث -دعوى من بعض الورثة دون بعض -ادعاء السداد -بينة غير موصلة -توجيه ميني للمدعى البالغ بنفي العلم عن سداد دين ملورثه -رد املدعى اليمن على املدعى عليه -أداء املدعى عليه اليمن يف حق احد املدعن دون غيره -دعوى على قاصر بالسداد -عدم النيابة يف اليمن -شبهة تقتضى تأجيل احلكم -تأجيل مين على قاصر حتى تكليفه -قرار بالتوقف عن حكم يف نصيب قاصر حتى تكليفه لعرض اليمن","document_number":"34275262","case_number":"33705143","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/22","year":"1434","subject":"قرض -عقد بيع -مطالبة بدين مورث -دعوى من بعض الورثة دون بعض -ادعاء السداد -بينة غير موصلة -توجيه ميني للمدعى البالغ بنفي العلم عن سداد دين ملورثه -رد املدعى اليمن على املدعى عليه -أداء املدعى عليه اليمن يف حق احد املدعن دون غيره -دعوى على قاصر بالسداد -عدم النيابة يف اليمن -شبهة تقتضى تأجيل احلكم -تأجيل مين على قاصر حتى تكليفه -قرار بالتوقف عن حكم يف نصيب قاصر حتى تكليفه لعرض اليمن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/7/22 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34275262 :‬‬\n                        ‫َر ْق ُم الدعوى‪33705143 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34308669‬تاريخه‪1434/8/29 :‬هـ‬\n\n\n\n     ‫قــرض ‪ -‬عقــد بيــع ‪ -‬مطالبــة بديــن مــورث ‪ -‬دعــوى مــن بعــض الورثــة‬\n     ‫دون بعــض ‪ -‬ادعــاء الســداد ‪ -‬بينــة غيــر موصلــة ‪ -‬توجيه ميني للمدعى‬\n     ‫البالــغ بنفــي العلــم عــن ســداد ديــن ملورثــه ‪ -‬رد املدعــى اليمــن علــى‬\n     ‫املدعــى عليــه ‪ -‬أداء املدعــى عليــه اليمــن يف حــق احــد املدعــن دون‬\n     ‫غيــره ‪ -‬دعــوى علــى قاصــر بالســداد ‪ -‬عــدم النيابــة يف اليمــن ‪ -‬شــبهة‬\n     ‫تقتضــى تأجيــل احلكــم ‪ -‬تأجيــل ميــن علــى قاصــر حتــى تكليفه ‪ -‬قرار‬\n     ‫بالتوقــف عــن حكــم يف نصيــب قاصــر حتــى تكليفــه لعــرض اليمــن‬\n     ‫عليــه ‪ -‬رد دعــوى ‪ -‬إلــزام بدفــع مبلــغ الديــن للورثــة ‪ -‬ســداد مبلــغ‬\n     ‫محكــوم بــه ‪ -‬حكــم واجــب االســتئناف لعــدم احلكــم للقاصــر بجميــع‬\n                                                                        ‫طلباتــه ‪.‬‬\n\n\n\n\n     ‫قــال يف كشــاف القنــاع (‪« )451/6‬وال تدخــل النيابــة يف اليمــن فــا‬\n     ‫يحلــف احــد عــن غيــره فلــوكان املدعــى عليــه صغيــرا أو مجنونــا لــم‬\n                ‫يحلــف ألنــه ال يعــول علــى قولــه ووقــف األمــر إلــى أن يكلفــا»‬\n\n\n\n\n‫‪79‬‬\n\f‫دعــوى املدعــي بالوكالــة واملوكلــة أصالــة عــن نفســها وبصفتهــا وليــة‬\n‫علــى ابنهــا القاصــر ضــد املدعــى عليــه ومضمــون الدعــوى أنــه توفــى‬\n‫مــورث املوكلــة وابنهــا وانحصــر ورثتــه يف والــده ويف زوجته املدعية وفى‬\n‫ابنهــا القاصــر الــذي هــو حتــت واليــة والدتــه وأنــه يوجــد بذمــة املدعــى‬\n‫عليــه ملــورث املدعيــة وابنهــا مبلغــا قــدره ســتة وســتون ألف ـ ًا وخمســمائة‬\n‫ريــال قرضــا وكذلــك مبلغــا قــدره واحــد وســتون ألــف ريــال ثمــن ســيارة‬\n‫اشــتراها املدعــى عليــه مــن مــورث املدعيــة وابنهــا وأن املدعــى عليــه لــم‬\n‫يســددها ويطالــب املدعــي وكالــة إلــزام املدعــى عليــه بتســليم نصيــب‬\n‫املدعيــة مبلغــا وقــدره خمســة عشــر ألفــا وتســعمائة وســبعة وثالثــون‬\n‫ريــا ًال وخمســون هللــة‪ ،‬ونصيــب ابنهــا القاصــر مبلغــا قــدره تســعون‬\n‫ألفــا وثالثمائــة واثنــا عشــر ريــا ًال وخمســون هللــة‪ .‬ومبواجهــة املدعــى‬\n‫عليــه صــادق علــى الدعــوى وقــرر أنــه ســدد مــن القــرض للمتوفــى حــال‬\n‫حياتــه جــزء ًا مــن املبلــغ ولــم يقــدم بينــة موصلــة علــى ذلــك وطلــب ميــن‬\n‫املدعيــة ورفضــت املدعيــة أداء اليمــن وطلبــت ميينــه وقــام بــأداء اليمــن‬\n‫وعليــه قــررت احملكمــة االعتــداد بيمينــه فيمــا يخــص حــق الزوجــة دون‬\n‫القاصــر وتأجيــل اليمــن يف حــق القاصــر حلــن تكليفــه وإلــزام املدعــى‬\n‫عليــه بســداد باقــي نصيــب األم وقــرر الطرفــان القناعــة وجــرى إرســال‬\n ‫األوراق حملكمــة االســتئناف لوجــود قاصــر وجــرى تصديــق احلكــم‪.‬‬\n\n\n\n\n                                                                                      ‫‪80‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة العامــة‬\n     ‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن الرئيــس برقــم ‪33705143‬‬\n     ‫يف ‪ 1433/12/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332245175‬يف‬\n     ‫‪ 1433/12/26‬ه ـ حضــر ‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫ا عــن ‪ ......‬أصالــة عــن نفســها وبصفتهــا وليــة‬    ‫رقــم ‪ ......‬بصفتــه وكي ـ ً‬\n     ‫علــى ابنهــا املولــود يف ‪1432/5/27‬ه ـ مبوجــب صــك الواليــة رقــم‬\n     ‫‪ 32153272‬يف ‪1432/7/3‬ه ـ الصــادر مــن محكمــة عنيــزة وذلــك‬\n     ‫مبوجــب الوكالــة رقــم ‪ 33343716‬يف ‪1433/7/15‬ه ـ الصــادرة مــن‬\n     ‫كتابــة عــدل عنيــزة وادعــى علــى احلاضــر معــه ‪ ......‬ســعودي اجلنســية‬\n     ‫ا يف دعــواه إنــه بتاريــخ ‪1432/6/17‬هـ‬      ‫مبوجــب الســجل املدنــي رقــم قائـ ً‬\n     ‫توفــى ‪ ......‬وهــو مــورث موكلــي املذكوريــن وانحصــر ورثتــه يف والــده‬\n     ‫وزوجتــه وابنــه القاصــر مبوجــب صــك حصــر الورثــة رقــم ‪32152337‬‬\n     ‫يف ‪1432/7/3‬ه ـ الصــادر مــن محكمــة عنيــزة ويوجــد بذمــة املدعــى‬\n     ‫عليــه ملــورث موك ّلــي املذكــور مبلــغ وقــدره ‪ 66500‬ســتة وســتون‬\n     ‫ألفــا وخمســمائة ريــال قرضــا وكذلــك مبلــغ وقــدره ‪ 61000‬واحــد‬\n     ‫وســتون ألــف ريــال قيمــة ســيارة ‪ ......‬موديــل ‪ 2002‬م اشــتراها املدعــى‬\n     ‫عليــه مــن املتوفــى املذكــور وإجمالــي املبلــغ الــذي بذمــة املدعــى عليــه‬\n     ‫ملــورث موك ّلــي ‪ 127500‬مائــة وســبعة وعشــرون ألــف وخمســمائة ريــال‬\n     ‫لــم يســدد املدعــى عليــه منهــا شــيئا للمتوفــى حــال حياتــه ولــم يســلم‬\n     ‫ملوك ّلــي شــيئا مــن نصيبهــم منهــا بعــد وفــاة مورثهــم أطلــب احلكــم علــى‬\n     ‫املدعــى عليــه بدفــع نصيــب موكلتــي زوجــة املتوفــى مــن املبلــغ املذكــور‬\n\n‫‪81‬‬\n\f‫وقــدره خمســة عشــر ألفــا وتســعمائة وســبعة وثالثــون ريــاال وخمســون‬\n‫هللــة ونصيــب ابنهــا املذكــور الــذي حتــت واليتهــا وقــدره تســعون ألفــا‬\n‫وثالثمائــة واثنــا عشــر ريــاال وخمســون هللــة هذه دعواي وبســؤال املدعى‬\n‫عليــه عــن دعــوى املدعــي وكالــة أجــاب بقولــه مــا ذكــره املدعــي مــن أن‬\n‫مــورث موكليــه املذكوريــن قــد تــويف وانحصــر ورثتــه يف املذكوريــن‬\n‫وأننــي اقترضــت مــن مورثهــم حــال حياتــه ســتة وســتني ألفــا وخمســمائة‬\n‫ريــال وأننــي اشــتريت الســيارة املذكــورة مــن املتوفــى املذكــور بواحــد‬\n‫وســتني ألــف ريــال فهــذا صحيــح ولكننــي ســددت مــن القــرض للمتوفــى‬\n‫حــال حياتــه ألفــن وثمامنائــة وخمســن ريــاال وســددت قيمــة الســيارة‬\n‫للمتوفــى كاملــة حــال حياتــه حيــث كانــت علــى أقســاط ولــم يبــق علــي‬\n‫مــن قيمتهــا شــيء وكان شــرائي للســيارة قبــل ثمــان ســنوات هكــذا‬\n‫أجــاب املدعــى عليــه وبعــرض جــواب املدعــى عليــه علــى املدعــي وكالــة‬\n‫قــال ال صحــة ملــا جــاء يف جــواب املدعــى عليــه مــن ســداده لقيمة الســيارة‬\n‫وجــزء مــن قيمــة القــرض هكــذا أجــاب املدعــي وكالة وبســؤال املدعى‬\n‫عليــه عــن بينتــه علــى الســداد قــال ال أعلــم لــي بينــة ويف جلســة أخــرى‬\n‫حضــر املدعــي وكالــة واملدعــى عليــه وقــرر املدعــى عليــه بقولــه إننــي‬\n‫وجــدت بينــة وأطلــب املهلــة إلحضارهــا ولذلــك فقــد أمهلــت املدعــى‬\n‫عليــه إلحضارهــا ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى‬\n‫عليــه وبســؤال املدعــى عليــه عــن البينــة التــي وعــد بإحضارهــا يف اجللســة‬\n‫الســابقة أحضــر ‪ ....‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫املعــرف بهــا مــن قبــل ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫وبســؤالها عمــا لديهــا مــن شــهادة قالــت أشــهد بــأن أخــي قــد أخبرنــي‬\n‫قبــل وفاتــه بأنــه قــد اســتلم قيمــة الســيارة ‪ ....‬كاملــة مــن أخــي املدعــى‬\n\n\n                                                                                      ‫‪82‬‬\n\f     ‫عليــه وقــال لــي أخــي املتوفــى إننــا خلصنــا مــن قيمــة الســيارة ونفــس هــذا‬\n     ‫الــكالم ســمعته مــن زوجتــه الســابقة ‪ ......‬ســورية اجلنســية هــذا مــا لــدي‬\n     ‫مــن شــهادة هكــذا شــهدت الشــاهدة وبعــرض الشــاهدة والشــهادة علــى‬\n     ‫املدعــي وكالــة قــال ال أعــرف املدعيــة وال أطعــن فيهــا والشــهادة ال أعلــم‬\n     ‫عنهــا هكــذا قــرر فســألت املدعــى عليــه هــل لديــه زيــادة بينــة فقــال‬\n     ‫نعــم وأطلــب املهلــة إلحضارهــا فأمهلتــه ويف جلســة أخــرى حضــر املدعــي‬\n     ‫وكالــة واملدعــى عليــه وأحضــر املدعــى عليــه معــه الشــاهد ‪ ....‬ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ......‬وبســؤال الشــاهد عن شــهادته‬\n     ‫قــال أشــهد بأننــي كنــت جالســا مــع والــدي واملدعــى عليــه وقــد قــال‬\n     ‫املدعــى عليــه لوالــدي إن الديــن الــذي بينــي أنــا وأخــي يف الســيارة‪.........‬‬\n     ‫قــد انتهــى وســددته كامــل املبلــغ هكــذا قــال املدعــى عليــه ولــم‬\n     ‫يكــن معنــا حــن قــال املدعــى عليــه هــذا الــكالم كمــا أننــي كنــت‬\n     ‫أشــاهد أوراقــا علــى طاولــة املدعــى عليــه تتضمــن اإلشــارة إلــى ديــن ال‬\n     ‫أذكــر تفاصيلــه وعليهــا توقيــع مــورث املدعــن هــذا مــا اذكــره هــذا‬\n     ‫مــا لــدي مــن شــهادة وبعــرض الشــاهد والشــهادة علــى املدعــي وكالــة‬\n     ‫قــال ال أعــرف الشــاهد وال أطعــن فيــه وأمــا مــا جــاء يف شــهادته فهــو‬\n     ‫غيــر موصــل كمــا أنــه لــم يشــهد بالســماع مــن مــورث موكلــي هكــذا‬\n     ‫أجــاب املدعــي وكالــة وقــد ســألت املدعــى عليــه هــل لديــك زيــادة بينــة‬\n     ‫فقــال أطلــب املهلــة لذلــك فأمهلتــه ويف جلســة أخــرى حضــر املدعــي‬\n     ‫وكالــة واملدعــى عليــه وقــد ســألت املدعــى عليــه هــل لديــه زيــادة بينــة‬\n     ‫فقــال ال أعلــم لــي زيــادة بينــة هكــذا قــرر وقــد اطلعــت علــى صــك حصــر‬\n     ‫الورثــة ووكالــة املدعــي فوجدتهــا كمــا ذكــر فبنــاء علــى مــا تقــدم مــن‬\n     ‫دعــوى املدعــي وكالــة املتضمنــة أن بذمــة املدعــى عليــه ملــورث موكليــه‬\n\n\n‫‪83‬‬\n\f‫‪127500‬مائــة وســبعة وعشــرون ألــف وخمســمائة ريــال لــم يســدد منهــا‬\n‫شــيئا وطلبــه احلكــم علــى املدعــى عليــه بدفــع نصيــب موكلتــه ونصيــب‬\n‫ابنهــا املذكــور الــذي حتــت واليتهــا مــن هــذا املبلــغ وإلقــرار املدعــى‬\n‫عليــه بأصــل اســتحقاق املبلــغ املدعــى بــه يف ذمتــه ودفعــه بأنــه ســدد‬\n‫جــزءا مــن القــرض وأنــه ســدد قيمــة الســيارة للمتوفــى كاملــة حــال‬\n‫حياتــه وإلنــكار املدعــي وكالــة ملــا دفــع بــه املدعــى عليــه ونظــرا إلــى‬\n‫أن املدعــى عليــه لــم يحضــر بينــة موصلــة ملــا دفــع بــه فشــهادة الشــاهدة ال‬\n‫تكفــي لوحدهــا وشــهادة الشــاهد الــذي أحضــره غيــر موصلــة ولذلــك‬\n‫فقــد أفهمــت املدعــى عليــه بــأن اليمــن تتوجــه علــى املدعــن علــى نفــي‬\n‫علمهــم بســداده لقيمــة الســيارة ومبلــغ ألفــن وثمامنائــة وخمســن ريــاال‬\n‫مــن القــرض فقــال أطلــب ميينهــم علــى ذلــك وبســؤال املدعــي وكالــة هــل‬\n‫موكلتــه مســتعدة باليمــن فيمــا يخصهــا دون مــا يخــص ابنهــا القاصــر‬\n‫قــال إن موكلتــي لــن حتلــف وتطلــب ميــن املدعــى عليــه فيمــا يخصهــا‬\n‫مــن املبلــغ علــى أنــه ســلم مــن القــرض مبلــغ ألفــن وثمامنائــة وخمســن‬\n‫ريــال ‪ 2850‬وأنــه ســدد قيمــة الســيارة كاملــة فــإذا حلــف فإنهــا ترضــى‬\n‫بيمينــه فيمــا يخصهــا وتطلــب احلكــم عليــه بدفــع مــا يخصهــا بعد خصم‬\n‫مــا يحلــف علــى ســداده وإجــراء املقتضــى الشــرعي نحــو حــق القاصــر‬\n‫هكــذا قــرر املدعــي وكالــة ولكــون املدعــي وكالــة مخــول بطلــب‬\n‫اليمــن وردهــا فقــد عرضــت ذلــك علــى املدعــى عليــه فقرر بقولــه ال مانع‬\n‫لــدي مــن اليمــن حلــق املدعيــة هكــذا قــرر املدعــى عليــه وبطلــب اليمــن‬\n‫مــن املدعــى عليــه حلــف قائــا واهلل العظيــم إننــي ســددت قيمــة الســيارة‬\n‫املذكــورة وقدرهــا واحــد وســتون ألــف ريــال كاملــة ألخــي املتــويف حــال‬\n‫حياتــه وســددت لــه مــن قيمــة القــرض ألفــن وثمامنائــة وخمســن ريــال‬\n\n\n                                                                                       ‫‪84‬‬\n\f     ‫هكــذا حلــف املدعــى عليــه فبنــاء علــى مــا تقــدم ولتوجــه اليمــن علــى‬\n     ‫املدعــن ورد املدعــي وكالــة اليمــن علــى املدعــى عليــه فيمــا يخصهــا‬\n     ‫مــن املبلــغ املدعــى بــه وأداء املدعــى عليــه اليمــن للمدعيــة ونظــرا إلــى‬\n     ‫أن القاصــر هنــا مدعــى عليــه يف الســداد وقــد قــال يف كشــاف القنــاع‬\n     ‫(‪( :)451/6‬وال تدخــل النيابــة يف اليمــن فــا يحلــف أحــد عــن غيــره‬\n     ‫فلــو كان املدعــى عليــه صغيــرا أو مجنونــا لــم يحلــف ألنــه ال يعــول علــى‬\n     ‫قولــه ووقــف األمــر إلــى أن يكلفــا) انتهــى وملــا تقــدم كلــه ولوجــود‬\n     ‫شــبهة تقتضــي تأجيــل احلكــم يف حــق القاصــر الــذي ادعــى املدعــى‬\n     ‫عليــه ســداده ألن علــى القاصــر ميينــا مؤجلــة إلــى تكليفــه وقــد ينــكل‬\n     ‫عنهــا أو يردهــا ولشــهادة املــرأة ورد والدتــه اليمــن علــى املدعــى عليــه‬\n     ‫فقــد قــررت التوقــف عــن احلكــم يف نصيــب القاصــر مــن قيمــة الســيارة‬\n     ‫املذكــورة وعــن احلكــم يف نصيــب القاصــر مــن مبلــغ ألفــن وثمامنائــة‬\n     ‫وخمســن ريــاال التــي ادعــى املدعــى عليــه ســدادها مــن القــرض حتــى‬\n     ‫يكلــف القاصــر لعــرض اليمــن عليــه ورددت دعــوى املدعيــة يف نصيبهــا‬\n     ‫مــن قيمــة الســيارة ومــن مبلــغ ألفــن وثمامنائــة وخمســن ريــاال التــي‬\n     ‫ادعــى املدعــى عليــه ســدادها مــن القــرض وألزمــت املدعــى عليــه بدفــع‬\n     ‫نصيــب املدعيــة وابنهــا القاصــر مــن الباقــي مــن القــرض وقــدره ثالثــة‬\n     ‫وســتون ألفــا وســتمائة وخمســون ريــاال للمدعيــة ســبعة آالف وتســعمائة‬\n     ‫وســتة وخمســون ريــاال وخمــس وعشــرون هللــة والبنهــا القاصــر خمســة‬\n     ‫وأربعــون ألفــا وخمســة وثمانــون ريــاال وإحــدى وأربعــون هللــة وبجميــع مــا‬\n     ‫تقــدم حكمــت وبعــرض احلكــم علــى الطرفــن قــررا القناعــة بــه وقــد‬\n     ‫أفهمــت الطرفــن أن احلكــم واجــب االســتئناف ألنــه لــم يحكم للقاصر‬\n     ‫بجميــع طلباتــه وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n\n\n‫‪85‬‬\n\f                                                ‫‪ .‬حــرر يف ‪ 1434/07/22‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بعنيــزة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بعنيــزة برقــم ‪ 33705143‬وتاريــخ ‪1433/12/26‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 332245175‬وتاريــخ ‪1433/12/26‬ه ـ ففــي يــوم األحــد‬\n‫املوافق‪1434/09/13‬ه ـ افتتحــت اجللســة الســاعة الثانيــة والربــع ظهــرا‬\n‫وقــد عــادت إلينــا املعاملــة مــن محكمــة االســتئناف بالقصيــم برقــم‬\n‫‪ 342027960‬يف ‪1434/ 9/ 6‬ه ـ وبرفقهــا قــرار محكمــة االســتئناف‬\n‫بالقصيــم رقــم ‪ 34308669‬يف ‪1434/ 8 / 29‬ه ـ املتضمــن املصادقــة‬\n‫علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                               ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/09/13‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي املــازم القضائــي لــدى فضيلــة الشــيخ‬\n‫القاضــي يف احملكمــة العامــة بعنيــزة وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بعنيــزة برقــم ‪33705143‬‬\n‫وتاريــخ ‪1433/12/26‬ه ـ املقيــدة باحملكمــة برقــم ‪332245175‬‬\n‫وتاريــخ ‪ 1433/12/26‬ه ـ ففــي يــوم اإلثنــن املوافــق ‪1434/10/12‬‬\n‫ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة ســعودي بالســجل رقــم‬\n‫بصفتــه وكيــا عــن ‪ /‬أصالــة عــن نفســها وبصفتهــا وليــة علــى ابنهــا‬\n‫املولــود يف ‪1432/5/27‬ه ـ مبوجــب صــك الواليــة رقــم ‪ 32153272‬يف‬\n‫‪1432/7/3‬ه ـ الصــادر مــن محكمــة عنيــزة وذلــك مبوجــب الوكالــة‬\n‫رقــم ‪ 333433716‬يف ‪1433/7/15‬ه ـ الصــادرة مــن كتابــة عــدل‬\n‫عنيــزة املخــول لــه فيهــا باالســتالم وقــرر بقولــه إننــي اســتلمت كامــل‬\n‫املبلــغ احملكــوم بــه ملوكلتــي وموليهــا القاصــر يف الصــك الصــادر‬\n\n\n                                                                                   ‫‪86‬‬\n\f     ‫برقــم ‪ 34275262‬يف ‪1434/7/22‬ه ـ مبوجــب الشــيك رقــم ‪ 94‬يف‬\n     ‫‪2013/8/19‬م املســحوب علــى مصــرف الراجحــي مببلــغ قــدره ســبعة‬\n     ‫آالف وتســعمائة وســتة وخمســون ريــاال وخمــس وعشــرون هللــة ومبوجــب‬\n     ‫الشــيك رقــم ‪ 93‬يف ‪2013/8/19‬م املســحوب علــى مصــرف الراجحــي‬\n     ‫وقــدره خمســة وأربعــون ألــف وخمــس وثمانــون ريــاال وواحــد وأربعــون‬\n     ‫هللــة هكــذا قــرر وبذلــك يكــون املدعــي وكالــة قــد اســتلم كامــل‬\n     ‫املبلــغ احملكــوم بــه يف هــذا الصــك وجــرى إحلاقــه حتــى ال يخفــى وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                          ‫حــرر يف ‪ 1434/10/12‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n     ‫الثانيــة مبحكمــة االســتئناف مبنطقــة القصيــم على املعاملــة الواردة من‬\n     ‫فضيلــة رئيــس احملكمــة العامــة مبحافظــة عنيــزة برقــم (‪)332245175‬‬\n     ‫وتاريــخ ‪ 1434/8/16‬هــ؛ اخلاصــة بدعــوى ع بالوكالــة عــن أصالــة عــن‬\n     ‫نفســها وواليــة علــى ابنهــا ؛ ضــد بشــأن املطالبــة مببلــغ مالــي ؛ املرفــق بهــا‬\n     ‫الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ املســجل برقــم‬\n     ‫(‪ )34275262‬وتاريــخ ‪1434/7/22‬هــ؛ املتضمــن أنــه قــرر التوقــف عــن‬\n     ‫احلكــم يف نصيــب القاصــر مــن قيمــة الســيارة املذكــورة وعــن احلكــم‬\n     ‫يف نصيــب القاصــر مــن مبلــغ ألفــن وثمامنائــة وخمســن ريــا ًال التــي ادعــى‬\n     ‫املدعــى عليــه ســدادها مــن القــرض حتــى يكلــف القاصــر لعــرض‬\n     ‫اليمــن عليــه ور َّد دعــوى املدعيــة يف نصيبهــا مــن قيمــة الســيارة ومــن‬\n     ‫مبلــغ األلفــن وخمســمائة ريــال وألــزم املدعــى عليــه بدفع نصيــب املدعية‬\n     ‫وابنهــا القاصــر مــن باقــي القــرض وقــدره ثالثــة وســتون ألف ـ ًا وســتمائة‬\n     ‫وخمســون ريــا ًال للمدعيــة ســبعة آالف وتســعمائة وســتة وخمســون ريــا ًال‬\n\n\n‫‪87‬‬\n\f‫وخمــس وعشــرون هللــة والبنهــا القاصــر خمســة وأربعــون ألفـ ًا وخمســة‬\n‫وثمانــون ريــا ًال وإحــدى وأربعــون هللــة وبذلــك حكــم؛ كمــا هــو مــدون‬\n‫ومفصــل فيــه؛ وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة؛ قررنــا‪ :‬التصديــق علــى احلكــم‪ .‬واهلل املوفــق؛ وصلــى‬\n                        ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪88‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":79,"source_page_end":88,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"90435c76698d308857d8ca6892834f3e2b2c72466b2309580bdad7513280fa63","normalized_text_hash":"60d57b8aca79e2b138d0370e877ec6063f29cba1bdc9a8e8d2370b828b8a67cf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p79-34275262"},{"id":"b334ecfa-36cf-5358-b6f2-6faa29042009","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -إقراض مبوجب حوالة بنكية -حكم على املدعى عليه بإعادة قرض مع دفعه انه مؤجل .","document_number":"34240537","case_number":"34146443","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/13","year":"1434","subject":"قرض -إقراض مبوجب حوالة بنكية -حكم على املدعى عليه بإعادة قرض مع دفعه انه مؤجل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/6/13 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34240537 :‬‬\n                        ‫َر ْق ُم الدعوى‪34146443 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 34340355‬تاريخه‪1434/10/26 :‬هـ‬\n\n\n\n     ‫قــرض ‪ -‬إقــراض مبوجــب حوالــة بنكيــة ‪ -‬حكــم علــى املدعــى عليــه‬\n                                       ‫بإعــادة قــرض مــع دفعــه انــه مؤجــل ‪.‬‬\n\n\n\n\n     ‫‪ -1‬قــال يف الــروض املربــع ‪ ( 40/5‬بــل يثبــت بدلــه يف ذمتــه أي ذمــة‬\n     ‫املقتــرض حــا ًال ولــو أجلــه املقتــرض ألنــه عقــد منــع فيــه التفاضــل‬\n     ‫فمنــع األجــل فيــه كالصــرف قــال اإلمــام القــرض حــال وينبغــي أن‬\n                                                               ‫يفــي بوعــده ) ‪.‬‬\n                  ‫‪ -2‬قال يف احلاشية ‪ ( 40/5‬ألن الوفاء بالوعد مستحب ) ‪.‬‬\n\n\n\n\n     ‫دعــوى املدعــى وكالــة ضــد املدعــى عليــه بــأن موكلــه قــد أقــرض‬\n     ‫املدعــى عليــه مبلغــا قــدره عشــرون ألــف جنيــه بريطانــي قرضــا حســن ًا‬\n     ‫عــن طريــق حوالــة بنكيــة وطلــب احلكــم علــى املدعــى عليــة بــأن يســلم‬\n     ‫ملوكلــه مبلــغ القــرض‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى‬\n     ‫ودفــع بــأن املدعــي أصالــة أعطــاه مهلــة يف الســداد وأن املهلــة لــم حتــل‪،‬‬\n     ‫أنهــى ناظــر القضيــة حكمــه بأنــه بنــاء علــى إقــرار املدعــى عليــه‬\n     ‫بالدعــوى ولقولــه يف الــروض املربــع « بــل يثبــت بدلــه يف ذمتــه أي ذمــه‬\n\n‫‪89‬‬\n\f‫املقتــرض حــاال ولــو اجلــه املقتــرض ‪ ...‬الــخ‪ ،‬فقــد صــدر احلكــم بإلــزام‬\n‫املدعــى عليــه بــأن يســلم للمدعــى املبلــغ املدعــى بــه ‪ ،‬قــرر املدعــى عليــه‬\n‫عــدم القناعــة ‪ ،‬صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة‬\n                                                     ‫باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي ‪ ....‬يف احملكمــة العامــة‬\n‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة باملدينــة املنــورة املســاعد برقــم ‪34146443‬‬\n‫وتاريــخ ‪1434/03/29‬ه ـ املقيــدة باحملكمــة برقــم ‪34779483‬‬\n‫وتاريــخ ‪ 1434/03/29‬ه ـ ففــي يــوم الثالثــاء املوافــق‪1434/06/13‬‬\n‫ه ـ حضــر‪ ....‬ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم ‪ ....‬بصفتــه‬\n‫الوكيــل الشــرعي عــن ‪ ....‬بريطانــي اجلنســية مبوجــب جــواز الســفر رقــم‬\n‫يف ‪ 2009/3/17‬صــادر مــن لنــدن مبوجــب الوكالــة رقــم ‪34371580‬‬\n‫يف ‪1434/3/25‬ه ـ صــادر مــن كتابــة العــدل باملدينــة املنــورة وادعــى‬\n‫ا يف دعــواه‪:‬‬‫علــى احلاضــر معــه مصــري اجلنســية باإلقامــة رقــم ‪ ....‬قائ ـ ً‬\n‫أقــرض موكلــي املدعــى عليــه مبلغ ـ ًا مقــداره عشــرون ألــف جنيــه‬\n‫بريطانــي (‪ )20000‬قرض ـ ًا حســن ًا يف شــهر ديســمبر ‪2012‬م وذلــك‬\n‫عــن طريــق حوالــة بنكيــة مــن لنــدن إلــى املدينــة املنــورة لذلــك يطالــب‬\n‫موكلــي باحلكــم علــى املدعــى عليــه بتســليمه جميــع مبلــغ القــرض‬\n‫ومقــداره عشــرون ألــف جنيــه بريطانــي حــا ًال هــذه دعــواي ‪ .‬وبســؤال‬\n‫املدعــى عليــه أجــاب قائ ـاً‪ :‬مــا ذكــره املدعــي بالوكالــة يف دعــواه‬\n\n                                                                                       ‫‪90‬‬\n\f     ‫كلــه صحيــح حيــث إنــه يف شــهر ديســمبر ‪2012‬م أقرضنــي موكلــه‬\n     ‫مبلغ ـ ًا مقــداره عشــرون ألــف جنيــه بريطانــي (‪ )20000‬وأعطانــي فيهــا‬\n     ‫مهلــة ســنة تنتهــي يف شــهر ديســمبر ‪2013‬م حيــث أرســلت لــه تعهــد‬\n     ‫باســترجاع هــذا القــرض يف شــهر ديســمبر ‪ 2013‬م عــن طريــق البريــد‬\n     ‫اإللكترونــي واســتلم البريــد وســكت ولــم يــرد ممــا يــدل علــى موافقتــه‬\n     ‫علــى املهلــة ومســتعد بإرجــاع كامــل مبلــغ القــرض ومقــداره عشــرون‬\n     ‫ألــف جنيــه بريطانــي (‪ )20000‬يف شــهر ديســمبر ‪2013‬م هــذا جوابــي‬\n     ‫ـاء علــى مــا تقــدم مــن الدعــوى‬  ‫‪ .‬ثــم إنــه وبعــد التأمــل يف القضيــة وبنـ ً‬\n     ‫واإلجابــة وإقــرار املدعــى عليــه بكامــل مبلــغ الدعــوى ومقــداره عشــرون‬\n     ‫ألــف جنيــه بريطانــي واســتعداده بإرجاعــه للمدعــي باألصالــة يف شــهر‬\n     ‫ديســمبر ‪2013‬م ولقولــه يف الــروض املربــع ‪( 40/5‬بــل يثبــت بدلــه يف‬\n     ‫ذمتــه أي ذمــة املقتــرض حــا ًال ولــو أجلــه املقتــرض ألنــه عقــد منــع فيــه‬\n      ‫التفاضــل فمنــع األجــل فيــه كالصــرف قــال اإلمــام القــرض حــالٌ‬\n     ‫وينبغــي أن يفــي بوعــده انتهــى قــال يف احلاشــية ‪ 40/5‬ألن الوفــاء بالوعــد‬\n     ‫مســتحب ) انتهــى لذلــك كلــه فقــد ثبــت لــدي أن بذمــة املدعــى عليــه‬\n     ‫للمدعــي باألصالــة مبلغ ـ ًا مقــداره عشــرون ألــف جنيــه بريطانــي يلزمــه‬\n     ‫تســليمها إليــه حــا ًال وبذلــك حكمــت وقنــع املدعــي بالوكالــة باحلكــم‬\n     ‫وأمــا املدعــى عليــه فلــم يقتنــع وطلــب محكمــة االســتئناف مبوجــب‬\n     ‫الئحــة اعتراضيــة فأجيــب لطلبــه وأفهــم بــأن لــه مهلــة ثالثــن يومـ ًا لتقدمي‬\n     ‫الالئحــة االعتراضيــة اعتبــار ًا مــن ‪1434/6/14‬ه ـ وهــو موعــد اســتالم‬\n     ‫الصــك وإذا تأخــر اكتســب احلكــم القطعيــة ففهــم ذلــك وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/6/13‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد أعيــدت إلينــا املعاملــة مــن محكمــة‬\n\n\n‫‪91‬‬\n\f‫االســتئناف مبكــة املكرمــة وبرفقهــا القــرار الصــادر مــن الدائــرة‬\n‫احلقوقيــة الرابعــة برقــم ‪ 34340355‬وتاريــخ ‪1434/10/26‬ه ـ املرفــق‬\n‫باملعاملــة واملظهــر علــى الصــك املتضمــن املوافقــة علــى احلكــم ‪ .‬قاضــي‬\n‫اســتئناف ختمــه وتوقيعــه ‪ ،‬قاضــي اســتئناف ختمــه وتوقيعــه ‪ ،‬رئيــس‬\n‫الدائــرة ختمــه وتوقيعــه ‪ ،‬لــذا جــرى إحلاقــه وبــاهلل التوفيــق ‪ .‬حــرر يف‬\n                                                            ‫‪1434/12/23‬ه ـ‬\n‫احلمد هلل وحده‪ ،‬والصالة والســام على رســول اهلل ‪ ،‬وبعد‪ :‬فقد جرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ القاضــي باحملكمــة العامــة باملدينــة املنــورة املســجل بعــدد‬\n‫(‪ )34240537‬وتاريــخ ‪1434/6/13‬ه ـ املتضمــن دعــوى وكالــة ضــد‬\n‫(مصــري اجلنســية) واحملكــوم فيــه مبــا دون بباطنــه وبدراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪92‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":89,"source_page_end":92,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2db294adefa7b07d367f64f5d4403b9c53b8e05d21b07feedb3e1233b575ff84","normalized_text_hash":"91ac9d2c42a65c768ad8418e32d024139ce9bf097977934cc66b8347aba07085","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p89-34240537"},{"id":"c160f135-649d-5347-9c1e-bb0dd3f2d195","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -رد بينة لقرينة قوية -إنكار البينة -إفهام املدعي بأن له مين املدعى عليه مغلظة يف الصيغة -حكم برد دعوى -حكم بإخاء سبيل املدعى عليه .","document_number":"34185871","case_number":"296271102","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":"الدائرة احلقوقية السادسة رقم 34258691يف 1434/7/3ه ونص","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/13","year":"1434","subject":"قرض -رد بينة لقرينة قوية -إنكار البينة -إفهام املدعي بأن له مين املدعى عليه مغلظة يف الصيغة -حكم برد دعوى -حكم بإخاء سبيل املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/4/13 :‬هـ‬\n                      ‫ُ‬                 ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34185871 :‬‬\n                        ‫َر ْق ُم الدعوى‪296271102 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34258791‬تاريخه‪1434/7/3 :‬هـ‬\n\n\n\n     ‫قــرض‪ -‬رد بينــة لقرينــة قويــة ‪ -‬إنــكار البينــة ‪ -‬إفهــام املدعــي بــأن لــه‬\n     ‫ميــن املدعــى عليــه مغلظــة يف الصيغــة ‪ -‬حكــم بــرد دعــوى ‪ -‬حكــم‬\n                                            ‫بإخــاء ســبيل املدعــى عليــه ‪.‬‬\n\n\n\n\n     ‫‪ -1‬مــا أخرجــه البخــاري ومســلم مــن حديــث أبــى هريــرة رضــى اهلل عنــه‬\n     ‫قــال‪ :‬قــال‪ :‬رســول اهلل صلــى اهلل عليــه وســلم « بينمــا امرأتــان معهمــا‬\n     ‫ابناهمــا جــاء الذئــب فذهــب بابــن إحداهمــا فقالــت هــذه لصاحبتهــا‬\n     ‫إمنــا ذهــب بابنــك انــت وقالــت األخــرى إمنــا ذهــب بابنــك أنــت‬\n     ‫فتحاكمــا إلــى داود فقضــى بــه للكبــرى فخرجتــا إلــى ســليمان بــن‬\n     ‫داود عليهمــا الســام فأخبرتــاه فقــال ائتونــي بالســكني اشــقه بينكمــا‬\n     ‫فقالــت الصغــرى ال تفعــل يرحمــك اهلل هــو ابنهــا فقضى بــه للصغرى‪.‬‬\n     ‫قــال ابــن القيــم يف الطــرق احلكيمــة بعــد أن ســاق اخلبــر ( إن اإلقــرار إذا‬\n     ‫كان لعلــه اطلــع عليهــا احلاكــم لــم يلتفــت إليــه ولذلــك الغينا إقرار‬\n     ‫املريــض مــرض املــوت مبــال لوارثــه النعقــاد ســبب التهمــة واعتمــاد ًا على‬\n     ‫قرينــه احلــال يف قصــد تخصيصــه وممــن خــرج احلديــث الســابق اإلمــام‬\n     ‫النســائي وقــد ترجــم عليــه تراجــم عــدة منهــا قولــه «احلكــم بخــاف مــا‬\n     ‫يعتــرف بــه احملكــوم لــه إذا تبــن للحاكــم أن احلــق يف غيــر مــا اعتــرف‬\n                                                                                  ‫به»‬\n\n‫‪93‬‬\n\f‫قــال ابــن القيــم معلقــا علــى هــذه الترجمــة يف إعــام املوقعــن ‪371/4‬‬\n                                      ‫(هــذا هــو العلــم اســتنباطا ودليــا ) ‪.‬‬\n‫‪ -2‬قــال العــز بــن عبدالســام يف قواعــده ‪( 125/2‬القاعــدة يف األخبــار‬\n‫والدعــاوى والشــهادات واالقاريــر وغيرهــا أن مــا كذبــه العقــل أو جــوزه‬\n‫وإحالتــه العــادة فهــو مــردود ومــا أبعدتــه العــادة مــن غيــر إحالــة فلــه‬\n‫رتــب يف البعــد والقــرب قــد يختلــف فيهــا فمــا كان أبعــد وقوعــا فهــو‬\n‫أولــى بالــرد ومــا كان اقــرب وقوعــا فهــو أولــى بالقبــول وبينهمــا رتــب‬\n                                                                       ‫متفاوتــة‪.‬‬\n\n\n\n\n‫دعــوى املدعــى وكالــة ضــد املدعــى عليــه وكالــة ومضمــون الدعــوى‬\n‫أن املدعــي اصالــة ســلم للمدعــى عليــه اصالــة مبلغــا قــدره مليونــان‬\n‫وخمســمائة وثمانيــة عشــر ألفــا ومئتــان وتســعون ريــا ًال ســلفه ولــم يردهــا‬\n‫املدعــى عليــه وطالــب املدعــى وكالــة إلــزام املدعــى عليــه اصالــة بتســليم‬\n‫املبلــغ املدعــى بــه ملوكلــه ‪ ،‬أجــاب املدعــى عليــه وكالــة باإلنــكار ‪،‬‬\n‫ســأل ناظــر القضيــة املدعــى وكالــة عــن بينتــه فأبــرز كمبيالــة تتضمــن‬\n‫اقــرار ًا منســوبا للمدعــى عليــه اصالــة يتضمــن صحــة الدعــوى ‪ ،‬جــري‬\n‫عــرض الكمبيالــة علــى املدعــى عليــه وكالــة فانكرها وقــرر أنها غير‬\n‫صحيحــة ‪ ،‬وجــه ناظــر القضيــة ســؤاال للمدعــى وكالــة عــن كيفيــة‬\n‫اســتالم املدعــى عليــه اصالــة املبلــغ مــن موكلــه فأجــاب املدعــى وكالــة‬\n‫انــه اســتلم املبلــغ مــن موكلــه نقــد ًا ‪ ،‬قــرر ناظــر القضيــة بأنــه نظــرا إلــى‬\n‫أن املدعــى وكالــة ذكــر أن موكلــه ســلم للمدعــى عليــه املبلــغ نقــد ًا‬\n‫وهــذا أمــر تبعــده العــادة إذ يبعــد عــادة أن يســلم شــخص آلخــر مبلغــا‬\n\n                                                                                           ‫‪94‬‬\n\f     ‫كبيــر ًا جــدا عــد ًا ونقــد ًا وملــا جــاء يف حيثيــات القضيــة مــن نصــوص‬\n     ‫شــرعية فقــد صــدر احلكــم بــرد الدعــوى وإخــاء ســبيل املدعــى عليــه‬\n     ‫وافهــم ناظــر القضيــة املدعــى وكالــة بــأن ملوكلــه ميــن املدعــى عليــه‬\n     ‫مغلظــة يف الصيغــة متــى طلبهــا فأبــى طلبهــا وقــرر املدعــى عليــه وكالــة‬\n     ‫أن موكلــه مســتعد ببــذل اليمــن عنــد طلبهــا منــه ‪ ،‬صــدق احلكــم مــن‬\n                                                           ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة العامــة‬\n     ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة مبحافظــة جــدة املســاعد برقــم ‪296271102‬‬\n     ‫وتاريــخ ‪1431/11/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3198454‬وتاريــخ‬\n     ‫‪1431/11/25‬ه ـ وبعــد عــدة جلســات ويف يــوم الســبت املوافــق‪:‬‬\n     ‫‪1434/04/13‬ه ـ حضــر ‪ ....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n     ‫رقــم‪ :‬الوكيــل عــن ‪ ....‬بصفتــه وكيــا عــن‪ .... :‬مبوجــب الوكالــة‬\n     ‫الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب جــدة برقــم‪ 43329 :‬يف‪:‬‬\n     ‫‪1432/12/19‬ه ـ واملخــول لــه فيهــا حــق املرافعــة واملدافعــة وتعيــن‬\n     ‫اخلبــراء واإلنــكار وحضــر حلضــوره ‪ ....‬ســعودي اجلنســية مبوجــب الهويــة‬\n     ‫الوطنيــة رقــم ‪ ....‬الوكيــل عــن ‪ ....‬مبوجــب الوكالــة الصــادرة مــن‬\n     ‫كتابــة العــدل الثانيــة بشــمال جــدة رقــم ‪ 80049‬وتاريــخ ‪1429/8/11‬هـ‬\n     ‫ثــم ادعــى املدعــي وكالــة قائــا‪ :‬إن موكلــي قــد ســلم للمدعــى عليــه‪:‬‬\n     ‫فلســطيني اجلنســية مبوجــب رخصــة اإلقامــة رقــم‪ :‬مبلغــا قــدره‪ :‬اثنــان‬\n     ‫مليــون وخمــس مئــة وثمانيــة عشــر ألــف ومئتــان وتســعون ريــاال وهــي‬\n‫‪95‬‬\n\f‫عبــارة عــن ســلفة‪ ،‬ولــم يردهــا حتــى اآلن‪ ،‬أطلــب إلــزام املدعــى عليــه‬\n‫بتســليم املبلــغ املدعــى بــه وقــدره‪ :‬اثنــان مليــون وخمــس مئــة وثمانيــة‬\n‫عشــر ألــف ومئتــان وتســعون ريــاال‪ ،‬هكــذا ادعــى‪ .‬أجــاب املدعــى عليــه‬\n‫وكالــة بقولــه مــا ذكــره املدعــي وكالــة كلــه غير صحيــح‪ ،‬وأطلب رد‬\n‫دعــوى املدعــي وإخــاء ســبيل موكلــي منهــا‪ ،‬هكــذا أجــاب‪ .‬وبســؤاله‬\n‫عــن بينتــه أجــاب قائــا‪ :‬بينتــي هــذه الورقــة وجــرى اطالعنــا عليهــا وهــذا‬\n‫نصهــا‪( :‬كمبيالــة‪ ،‬اســتحقاق الدفــع ‪1430/2/1‬هـ مبلغهــا‪2518290 :‬‬\n‫ريــال املديــن‪ :‬إقامــة‪ . . . :‬أتعهــد أنــا املديــن املوقــع أعــاه بــأن أدفــع ألمــر‬\n‫الســيد املبلــغ املرقــوم أعــاه وقــدره‪ :‬اثنــان مليــون وخمــس مئــة وثمانيــة‬\n‫عشــر ألــف ومئتنــا وتســعون ريــاال بــدون تأخيــر وقــت الطلــب ‪ . . .‬حــررت‬\n‫يف‪2008/3/12 :‬م شــاهد توقيعــه املديــن (بــدون اســم) توقيعــه)‪ .‬ا‪ .‬ه ـ‬\n‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب قائــا‪ :‬مــا جــاء يف هــذه‬\n‫الكمبيالــة غيــر صحيحــة والتوقيــع الــذي عليهــا ليــس توقيــع موكلــي‪،‬‬\n‫هكــذا أجــاب‪ .‬وبســؤال املدعــي وكالــة عــن زيــادة بينــة أجــاب قائــا‪:‬‬\n‫ليــس لــدي ســوى مــا قدمــت‪ ،‬هكــذا أجــاب‪ .‬وبســؤاله كيــف ســلم‬\n‫موكلــه املبلــغ املدعــى بــه للمدعــى عليــه أصالــة أجــاب قائــا‪ :‬ســلمه‬\n‫نقــدا هكــذا أجــاب‪ .‬وبدراســة القضيــة وتأملهــا‪ ،‬ومبــا أن املدعــي‬\n‫وكالــة قــد ذكــر أن موكلــه أقــرض املدعــى عليــه مبلغــا قــدره‪ :‬اثنــان‬\n‫مليــون وخمــس مئــة وثمانيــة عشــر ألــف ومئتنــا وتســعون ريــال‪ ،‬ومبــا أن‬\n‫صحــة دعــواه جملــة وتفصي ـاً‪ ،‬ومبــا أن‬     ‫املدعــى عليــه قــد دفــع بعــدم ّ‬\n‫املدعــي وكالــة ذكــر أن موكلــه سـلّم املبلــغ املدعــى بــه للمدعــى عليــه‬\n‫عـ ّـد ًا ونقــداً‪ ،‬وهــذا أمــر ُتبعــده العــادة؛ إذ يبعــد عــادة أن ُيس ـلّم شــخص‬\n‫آلخــر مبلــغ كثيــر جــد ًا عـ ّـد ًا ونقـ ّـداً‪ ،‬ومــا أحالتــه العــادة أو أبعدتــه فهــو‬\n\n\n                                                                                               ‫‪96‬‬\n\f     ‫مــردود بقــول ابــن عبــد الســام يف قواعــده ‪( :125/2‬القاعدة يف األخبار‬\n     ‫والدعــاوى والشــهادات واألقاريــر وغيرهــا أن مــا كذبــه العقــل أو جــوزه‬\n     ‫وأحالتــه العــادة فهــو مــردود‪ ،‬وأمــا مــا أبعدتــه العــادة مــن غيــر إحالــة‬\n     ‫فلــه رتــب يف البعــد والقــرب قــد يختلــف فيهــا‪ ،‬فمــا كان أبعــد وقوع ـ ًا‬\n     ‫فهــو أولــى بالــرد ومــا كان أقــرب وقوع ـ ًا فهــو أولــى بالقبــول وبينهمــا‬\n     ‫رتــب متفاوتــة)‪ ،‬وألن اإلقــرار (الكمبيالــة) ـ علــى فــرض ثبوتــه ـ إذا‬\n     ‫شــهدت قرينــة قويــة بــر ّده لــم يعمــل به‪،‬برهــان ذلــك مــا أخرجــه البخــاري‬\n     ‫ومســلم مــن حديــث أبــي هريــرة رضــي اهلل عنــه قــال‪ :‬قــال رســول اهلل‬\n     ‫صلــى اهلل عليــه وســلم‪( :‬بينمــا امرأتــان معهمــا ابناهمــا جــاء الذئــب‬\n     ‫فذهــب بابــن أحدهمــا فقــال هــذه لصاحبتهــا إمنــا ذهــب بابنــك أنــت‬\n     ‫وقالــت األخــرى إمنــا ذهــب بابنــك أنــت فتحاكمــا إلــى داود فقضــى بــه‬\n     ‫للكبــرى فخرجتــا إلــى ســليمان بــن داود ـ عليهمــا الســام ـ فأخبرتــاه ‪،‬‬\n     ‫فقــال ائتونــي بالســكني أشــقه بينكمــا ‪ ،‬فقالــت الصغــرى ‪ :‬ال تفعــل‬\n     ‫يرحمــك اهلل هــو ابنهــا فقضــى بــه للصغــرى)‪ ،‬قــال ابــن القيــم يف الطــرق‬\n     ‫احلكميــة ص ‪ 6‬بعــد أن ســاق اخلبــر‪( :‬إن اإلقــرار إذا كان لعلــة اطلــع‬\n     ‫عليهــا احلاكــم لــم يلتفــت إليــه‪ ،‬ولذلــك ألغينــا إقــرار املريــض مــرض‬\n     ‫املــوت مبــال لوارثــه النعقــاد ســبب التهمــة واعتمــاد ًا علــى قرينــة احلــال يف‬\n     ‫قصــد تخصيصــه)‪ ،‬وممــن خـ ّـرج احلديــث الســابق اإلمــام النســائي وقــد‬\n     ‫ترجــم عليــه عــدة تراجــم منهــا قولــه ‪( :‬احلكــم بخــاف مــا يعتــرف بــه‬\n     ‫احملكــوم لــه إذا تبــن للحاكــم أن احلــق يف غيــر مــا اعتــرف بــه)‪ ،‬قــال‬\n     ‫ابــن القيــم معلقـ ًا علــى هــذه الترجمــة يف إعــام املوقعــن ‪( :371/4‬هــذا‬\n     ‫هــو العلــم اســتنباط ًا ودليـاً)‪ ،‬لذلــك ك ّلــه فقــد أعلمـ ُـت املدعــي وكالــة‬\n     ‫بــأن موكلــه ال يســتحق مــا ادعــاه جتــاه املدعــى عليــه مــن ثمــن القــرض‪،‬‬\n\n\n‫‪97‬‬\n\f‫ورددت دعــواه وأخليــت ســبيل املدعــى عليــه منهــا‪ ،‬وبذلــك قضيــت‪.‬‬\n‫وبإعــان احلكــم قــرر املدعــى عليــه وكالــة قناعتــه باحلكــم‪ ،‬وقــرر‬\n‫املدعــي وكالــة اعتراضــه فجــرى تســليمه نســخة مــن احلكــم وأفهــم‬\n‫بــأن لــه احلــق يف تقــدمي اعتراضــه ملــدة ثالثــن يومــا اعتبــارا مــن هــذا‬\n‫اليــوم وإذا انتهــت املــدة ولــم يقــدم اعتراضــه ســقط حقــه يف االعتــراض‬\n‫واكتســب احلكــم القطعيــة‪ .‬وأفهمــت املدعــي وكالــة بــأن ملوكلــه ميــن‬\n‫املدعــى عليــه املغلظــة بهــذه الصيغــة‪( :‬واهلل الــذي ال إلــه إال هــو عالــم‬\n‫الغيــب والشــهادة الرحمــن الرحيــم الطالــب الغالــب الضــار النافــع الــذي‬\n‫يعلــم خائنــة األعــن ومــا تخفــي الصــدور أننــي لــم اســتلم مــن املدعــي‬\n‫أصالــة‪ :‬مبلغــا قــدره‪ :‬اثنــان مليــون وخمــس مئــة وثمانيــة عشــر ألــف‬\n‫ومئتــان وتســعون ريــاال) متــى طلبهــا‪ ،‬فأبــى طلبهــا وليــس ل ــه إال ذلــك‬\n‫متــى طلبهــا‪ ،‬وقــد قــرر املدعــى عليــه وكالــة أن موكلــه مســتعد ببــذل‬\n‫اليمــن عنــد طلبهــا منــه‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                  ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/13‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/07/23‬ه ـ وقــد‬\n‫عــادت املعاملــة مــن محكمة االســتئناف مبكة املكرمــة وبرفقها قرار‬\n‫الدائــرة احلقوقيــة السادســة رقــم ‪ 34258691‬يف ‪1434/7/3‬ه ـ ونــص‬\n‫احلاجــة منــه‪( :‬وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم) ا‪.‬ه ـ وللبيــان جــرى إثباتــه وأمــرت بإحلاقــه‬\n‫بالصــك والســجل‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/23‬ه ـ‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد‪ :‬فق ــد ج ــرى‬\n‫م ّنــا نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n\n\n                                                                                     ‫‪98‬‬\n\f     ‫االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا احلكــم‬\n     ‫الصــادر مــن فضيلــة الشــيخ ‪ ....‬القاضــي باحملكمــة العامــة بجــدة‬\n     ‫واملســجل بع ــدد‪ 34185871‬وتاريــخ ‪1434/4/13‬هـ ـ املتضمــن دعــوى‬\n     ‫ضــد احملكــوم في ــه مبــا دون باطــن الصــك‪ ،‬وبدراس ــة احلكــم وص ــورة‬\n     ‫ضبط ــه و الئحتــه االعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم‪ ،‬واهلل‬\n        ‫املوفــق‪ .‬وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪99‬‬\n\f","legal_articles":[